(window.SITE_LANG_DATA = window.SITE_LANG_DATA || {})["mk"] = {"ui":{"skip":"Прескокни до содржината","back":"← Назад кон AI-gile","lang.button":"Јазик: {name}","lang.dialog":"Избери јазик","lang.search":"Пребарај јазици","lang.none":"Нема јазик што одговара","lang.notYet":"{name} сè уште не е преведен","theme.aria":"Промени тема: светла, темна или црна","theme.toLight":"Префрли на светла тема","theme.toDark":"Префрли на темна тема","theme.toBlack":"Префрли на црна тема (вистинска црна, пријатна за OLED екрани)","words.underline":"Подвлечи ги овие зборови на страницата","words.underlineHelp":"Застани со глувчето врз збор подвлечен со точки или допри го за да видиш што значи.","words.col.todo":"Картички избрани за сега: тимот ќе почне со нив следно.","words.col.doing":"Една ВИ работи на оваа картичка токму сега.","words.col.review":"Една ВИ ја завршила работата; друга ја проверува пред да стигне до тебе.","words.col.verify":"Чека тебе: пробај го и кажи дали работи.","words.col.team":"Твоите белешки или одговори, кои чекаат тимот да ги земе.","words.col.done":"Завршено и прифатено.","index.title":"AI-gile: твојот AI тим за развој, на една табла","index.description":"AI-gile е канбан табла за AI тимови што пишуваат код. Тие работат додека спиеш; ти останува една кратка купчинка: што да одлучиш, што да тестираш и што да прифатиш.","hero.logoAlt":"Икона на таблата AI-gile","hero.h1.html":"Твојот AI тим за развој, на една&nbsp;табла.","hero.alpha":"🐣 Затворена пред-алфа","hero.alphaTitle":"Рано и недовршено: фала што пробуваш!","hero.lede":"Градат додека спиеш. Се будиш со една кратка купчинка: неколку прашања, неколку работи за тестирање, еден-два виолетови дијаманти. Кликни, прифати и назад кон кафето.","dl.windows":"Апликација за Windows","dl.browser":"Пушти ја во прелистувач","dl.messenger":"📱 Messenger за твојот телефон","dl.soon":"Наскоро","dl.notify":"🔔 Јави ми кога ќе се отвори","dl.notifySmall":"Алфа или бета","hero.secondary":"Agile, но тимот никогаш не бара кафе на стоење. (Stand-up сепак имаат.)","pitch.h2":"AI-gile со онолку зборови колку што сакаш","pitch.lede":"Избери должина, од еден збор до 144. Секоја должина е посебен опис, напишан токму за таа големина. Влечи го лизгачот или користи ги стрелките.","pitch.rangeLabel":"Должина во зборови","pitch.dice":"🎲 друга верзија","pitch.words.one":"{n} збор","pitch.words.other":"{n} зборови","pitch.letters.one":"{n} буква","pitch.letters.other":"{n} букви","pitch.chars.one":"{n} знак","pitch.chars.other":"{n} знаци","count.line.html.one":"{n} картичка на таблата во моментов","count.line.html.other":"{n} картички на таблата во моментов","people.humans.html.one":"👥 {n} човек","people.humans.html.other":"👥 {n} луѓе","people.agents.html.one":"🤖 {n} агент","people.agents.html.other":"🤖 {n} агенти","people.working.html.one":"⚡ {n} работи во моментов","people.working.html.other":"⚡ {n} работат во моментов","pre.title":"AI-gile: нешто се гради","pre.description":"Овде нешто се гради: табла на која AI тимови го градат она што ќе го побараш и те учат додека работат. Засега затворена пред-алфа со пријатели.","pre.h1":"Овде нешто се гради. 🤫","pre.line":"Табла на која AI тимови го градат она што ќе го побараш и те учат додека работат. Засега затворена пред-алфа со пријатели.","pre.btn":"🔔 Јави ми кога ќе се отвори","pre.peek":"Зад стаклото: вистинската табла, во живо. Секоја картичка е обоена лента.","pre.peekFake":"Зад стаклото: вака изгледа табла што работи.","pre.night":"🌙 Ноќниот чувар е задолжен · 😴 човекот почива","features.aria":"Што прави","f.pile.h":"Една купчинка за тебе","f.pile.html":"<b>За тебе</b> го содржи сè што чека тебе, од сите проекти: прашања, работи за тестирање, задачи што може да ги направи само човек. Твојата редица кажува што е следно и колку трае.","f.sleep.h":"Тимови што работат додека спиеш","f.sleep.p":"Секој проект има лидер и тим од AI агенти. Коментирај на картичка и тимот се буди, ја завршува работата и ти ја враќа со чекори што ги следи и уморен човек.","f.tester.h":"Прво проверува AI тестер","f.tester.p":"Пред да стигне нешто до тебе, тестерот ги следи чекорите во копија на апликацијата и покажува што видел, со снимка од екранот. Прелистај ги поминатите и прифати со еден клик.","f.proof.h":"Докази, а не ветувања","f.proof.p":"Секое предавање покажува што се променило: датотеките, разликите, снимките од екранот. Не мора да ја отвораш секоја апликација за да видиш дали е готово.","f.chat.h":"Разговарај со твоите лидери","f.chat.p":"Лента во стил на Discord: една икона по проект, виолетови дијаманти за она што те бара тебе. Испрати идеја до лидерот; тој ја претвора во картички и план, со копче ✅ Тргнуваме.","f.tidy.h":"Сама се средува","f.tidy.p":"Сродните картички се спојуваат во една, збунетите наслови се поправаат, а проверката на токени го одржува кодот скромен. Помалку нешта меѓу кои се префрлаш, помалку за размислување.","f.private.h":"Твоја, на твојот компјутер","f.private.li1":"Таблата работи на твојот сопствен компјутер и одговара само на тебе.","f.private.li2":"Приватните пораки меѓу луѓе се шифрирани од крај до крај.","f.private.li3":"Без сметки, без следачи, без колачиња.","f.lang.h":"На твојот јазик","f.lang.p":"Над 120 јазици, од холандски, велшки и јапонски до гусарски, Јода и клингонски, со брзо враќање на англиски за стручните термини.","f.service.h":"Од идеја до вистинска услуга","f.service.p":"Си изградил нешто со AI што луѓето сега го користат? Означи го како услуга и таблата ти помага добро да ја водиш: проверки на достапност, јавна страница со статус, инциденти со анализа, промени што бараат Go, резервни копии што се проверуваат секој ден. Помошта те учи на секој чекор додека одиш.","msgr.h2":"AI-gile Messenger: твојот тим во џеб","msgr.p1":"Зборувај со својот AI тим без да ја отвораш таблата. Разговарај со водачите на проектите и со пријателите, види ги чекорите за тестирање на картичката и одговори на нив, сè од телефонот.","msgr.p2":"За да го поврзеш, скенирај QR-код на својата табла. Прв пат? Пријателски демо разговор ќе ти покаже сè.","msgr.when":"Прво за Android, потоа веб-верзија за телефони и iPhone.","msgr.who":"Твојот водач на проектот","msgr.b1":"Поправката за темниот режим е готова. Да ти ги пратам чекорите за тестирање?","msgr.b2":"Да, те молам!","msgr.b3":"1. Отвори Поставки. 2. Избери Темна. Дали изгледа добро?","tl.aria":"Временска лента од првиот разговор до патоказот","tl.h2":"Од првиот разговор до она што следува","tl.lede":"Вистински датуми и часови, во твојата временска зона. По денес е план, без ветени датуми.","tl.today":"Денес","tl.planned":"планирано","tl.doing":"во тек","tl.cards.one":"{n} картичка","tl.cards.other":"{n} картички","join.h2":"Придружи се","join.lede":"AI-gile го гради брадест чудак со AuDHD и неколку битки со менталното здравје, и голем број трпеливи агенти. За сега е приватна, во затворена алфа со пријатели. Сакаш да пробаш кога ќе се отвори?","join.btn":"Пријави интерес","join.small":"Ќе ти пишеме на е-пошта, ништо друго","footer.tag":"AI-gile. Без следачи, без колачиња, без кафе на стоење.","footer.licence":"Деловна лиценца","footer.status":"Статус","footer.privacy":"Што чуваме","footer.thanks":"Повиците благодарение на ChilledChat","form.sending":"Се испраќа…","form.failed":"Не успеа: обиди се повторно подоцна.","form.offline":"Не можевме да стигнеме до AI-gile: обиди се повторно подоцна.","form.keep":"Ова го користиме само за да ти одговориме, а потоа го бришеме. Без следачи, без колачиња.","form.keepLink":"Што чуваме","interest.title":"AI-gile: јави ми кога ќе се отвори алфата","interest.description":"Остави е-пошта за да дознаеш кога ќе се отвори затворената алфа или бета на AI-gile.","interest.h1":"🔔 Јави ми кога ќе се отвори","interest.lede":"AI-gile е во затворена пред-алфа. Остави е-пошта и ќе ти пишеме еднаш, кога ќе има место за тебе.","interest.email":"Твојата е-пошта","interest.which":"Кое тестирање?","interest.alpha":"Затворена алфа: рано, грубо, многу промени","interest.beta":"Бета: поцврста, подоцна","interest.both":"Кое и да е, она што ќе дојде прво","interest.submit":"Запиши ме на списокот","interest.thanks":"Фала! Си на списокот.","licence.title":"AI-gile: деловна лиценца","licence.description":"Ја користиш AI-gile во твојата фирма? Побарај бесплатна деловна лиценца.","licence.h1":"📜 Деловна лиценца","licence.lede":"Ја користиш AI-gile на работа? Кажи ни кој си и што работиш. Ако носи некаква корист, лиценцата е бесплатна.","licence.company":"Фирма","licence.website":"Веб-страница","licence.what":"Што работиш","licence.how":"Како му помага на светот","licence.email":"Е-пошта","licence.submit":"Аплицирај","licence.thanks":"Фала! Ќе одговориме по е-пошта.","status.title":"Статус на AI-gile","status.h1":"Статус на AI-gile","status.quiet":"Сè е мирно","status.intro":"Дали AI-gile работи во моментов? Оваа страница ги проверува веб-страницата, споделувањето табли, повиците и преземањето на секои 5 минути.","status.up":"Работи (одговори за {ms} ms)","status.slow":"Не одговори на последната проверка, се обидувам повторно","status.down":"Не работи: не одговори на последните две проверки","status.svc.web":"Веб-страница","status.svc.web.offers":"Оваа страница: што е AI-gile и формуларот за интерес","status.svc.boards":"Споделување табли","status.svc.boards.offers":"Јавни табли, пораки меѓу пријатели и покани","status.svc.calls":"Повици","status.svc.calls.offers":"Глас, видео и споделување екран во AI-gile","status.svc.download":"Преземање","status.svc.download.offers":"Инсталерот за Windows и линковите за покани","status.checking":"Проверувам…","status.offline":"Моментално не можам да стигнам до услугата за статус (се обидувам повторно)","status.updated":"ажурирано {ago}","status.justNow":"токму сега","status.min":"пред {n} мин","status.hours":"пред {n} ч","status.days":"пред {n} д","privacy.title":"AI-gile: што чуваме","privacy.h1":"Што чуваме","privacy.lede":"Накратко: само она што ни го праќаш, и не задолго.","privacy.only":"Само она што ни го праќаш: она што ќе го напишеш во формулар, како твојата е-пошта. Ништо друго за тебе.","privacy.sealed":"Се запечатува за нашиот сервер да не може да го прочита: во твојот прелистувач, пред да тргне (кај постар прелистувач, во мигот кога ќе пристигне). Само нашата табла може да го отвори.","privacy.server":"Се брише од серверот штом стигне до нашата табла. Сè што таму ќе остане и по 30 дена, сепак се брише.","privacy.board":"На нашата табла го чуваме само додека не ти одговориме, а потоа го бришеме и таму.","privacy.none":"Без следачи, без колачиња, без аналитика.","privacy.local":"Твојот јазик и изборот на светла или темна тема остануваат во твојот прелистувач. Никогаш не ни се испраќаат.","privacy.ask":"Сакаш да се избрише порано? Одговори на нашата е-пошта и кажи ни.","live.h2":"Гледајте како се гради, во живо","live.caption":"Секоја картичка е скриена: ја гледате формата на работата, не зборовите.","live.watching.one":"во живо: {n} гледа","live.watching.other":"во живо: {n} гледаат","live.last.now":"Последната картичка е преместена токму сега","live.last.min.one":"Последната картичка е преместена пред {n} мин.","live.last.min.other":"Последната картичка е преместена пред {n} мин.","live.last.hour.one":"Последната картичка е преместена пред {n} ч.","live.last.hour.other":"Последната картичка е преместена пред {n} ч.","live.last.day.one":"Последната картичка е преместена пред {n} д.","live.last.day.other":"Последната картичка е преместена пред {n} д.","live.offline":"Таблата во живо малку се одмора. Навратете наскоро.","live.cols":"Backlog|За работа|Во тек|Тимот проверува|За твое тестирање|За тимот|Готово"},"lines":{"unit":"words","sizes":[{"n":1,"texts":["Канбан.","Роботи.","Делегирано."]},{"n":2,"texts":["Роботски канбан.","Агенти, организирани.","Идеи, изградени."]},{"n":3,"texts":["Канбан за роботи.","Идеите стануваат функции.","Бесплатен агентски канбан."]},{"n":5,"texts":["Канбан табла управувана од агенти.","Ти пишуваш картички. Агентите градат.","Бесплатно, локално, тестирано, малку смешно."]},{"n":8,"texts":["Бесплатна канбан табла каде работат AI агенти.","Напиши идеја. Агентите ја градат. Ти прифаќаш.","Agile за еден човек и многу трпеливи роботи."]},{"n":13,"texts":["Канбан табла на твојот компјутер, каде AI агентите ги земаат картичките една по една.","Напиши идеја. Тим од агенти ја гради. Тестер ја проверува и покажува што видел.","Без сметки, без следачи: табла, неколку роботи и ти, кој одлучуваш за сè."]},{"n":21,"texts":["AI-gile е канбан табла за работа со AI агенти што пишуваат код. Тие ги земаат картичките, а ти ги тестираш и прифаќаш.","Секој проект има свој лидер и тим од AI агенти. Коментирај на која било картичка и тимот веднаш се зафаќа со работа.","Бесплатна лична табла со задачи што работи на твојот компјутер. Работниците се роботи. Оној што вели „да“ си ти."]},{"n":34,"texts":["Ги ставаш идеите на таблата. Тим од AI агенти ги претвора во функции што работат, ги тестира и ти ги враќа со чекори за пробање. Ништо не е готово додека не кажеш ти.","AI-gile е домашна канбан табла што ја изгради Rich, најмногу со помош на агентите со кои сега управува. Бесплатна е, работи на твојот компјутер и се дели со пријатели, не се продава.","Замисли обична канбан табла со колони од Backlog до Готово, само што картичките ги земаат AI агенти. Известуваат за напредокот, прашуваат кога ќе се заглават и секогаш чекаат твое одобрение."]},{"n":55,"texts":["AI-gile е канбан табла каде тимот е составен од AI агенти. Секој проект има лидер што ја планира работата и помагачи што ја градат. Кога функцијата е готова, AI тестер ја испробува и прави снимка од екранот, па стигнува во твојата купчинка. Прифати ја или коментирај, и тие ја доработуваат.","Започна како начин еден човек да следи многу AI сесии за пишување код одеднаш, а израсна во вистинска табла. Работи на твојот компјутер, не бара сметка и нема следачи. Бесплатна е за пријатели и за секој љубопитен. Исто така е недовршена, па очекувај груби рабови и по некое изненадување.","Еве ја искрената верзија. Идеите сè уште мораш да ги измислиш ти, а резултатите сè уште мораш да ги провериш. AI-gile го прави сето она помеѓу: ги држи картичките во ред, го буди вистинскиот агент кога ќе коментираш, покажува што точно се променило и сè го собира во една кратка купчинка за тебе."]},{"n":89,"texts":["AI-gile е бесплатна канбан табла што ја пушташ на твојот компјутер. Наместо луѓе, секој проект има тим од AI агенти: лидер што ги претвора твоите идеи во картички и план, и помагачи што ги земаат картичките по приоритет. Кога нешто е изградено, AI тестер ги следи чекорите за тестирање и ти покажува што видел. Потоа чека во една купчинка наречена За тебе. Ти ја прифаќаш или коментираш, а тимот пробува повторно. Ништо не стигнува до Готово без тебе.","Неколку работи што можеби не ги очекуваш. Ноќна стража ја одржува колоната За работа полна додека спиеш, избирајќи картички што не бараат одговор од тебе. Бројачот на токени покажува колку агентите потрошиле денес и оваа недела, а режимот Без токени им кажува да престанат да трошат. Можеш да пишуваш на пријатели, а приватните пораки се шифрирани од крај до крај. Таблата зборува околу 120 јазици, меѓу кои холандски, фламански, гусарски и клингонски. Ништо од тоа не се плаќа, а никој не се обидува да ти го продаде.","AI-gile е мал, личен проект, а не компанија. Rich сакаше да внимава на повеќе AI проекти за пишување код без да ја отвора секоја апликација, па тој и агентите изградија табла за тоа, а потоа со таблата го изградија остатокот. Во затворена пред-алфа е, што значи дека работи, повеќе-помалку, за неколку пријатели. Нема страница со цени, нема билтен и нема план за раст. Ако ти звучи корисно, можеш да побараш да пробаш кога ќе се отвори малку повеќе."]},{"n":144,"texts":["AI-gile е канбан табла за еден човек и многу AI агенти. Работи на твојот сопствен компјутер и е сосема бесплатна. Додаваш проекти, а секој проект добива лидер и мал тим. Разговараш со лидерот, малку како на Discord, и опишуваш идеја; лидерот ја претвора во картички и план, па чека да притиснеш Тргнуваме. Тимот ги работи картичките по приоритет, преку едноставна командна линија направена за јазични модели. Пред нешто да ти се врати, AI тестер ги следи чекорите во копија на апликацијата и приложува снимка од екранот. Завршената работа стигнува во твојата купчинка со променетите датотеки и разликите. Ја прифаќаш или оставаш коментар, а тимот се буди и пробува повторно. Таблата и сама се чисти: сродните картички се спојуваат. Картичка во Готово може да префрли само ти. Никој друг, ни најдобриот агент.","Грубо, ова е еден ден со AI-gile. Навечер оставаш неколку коментари: ова копче е на погрешно место, таа листа треба да се подреди, може ли темен режим. Одиш да спиеш. Агентите ги читаат коментарите, ги прават промените, ги тестираат и ти ги враќаат. Ако За работа остане празно, ноќната стража го полни од backlog со картички што не бараат одговор од тебе. Наутро има една кратка купчинка: неколку прашања и неколку работи за пробање, секоја со чекори што ги следи и поспан човек и со снимка како работи. Кликаш, ги прифаќаш добрите и ги враќаш другите. Ако нешто не ти е јасно, само коментираш и пак стигнува до тимот. Бројачот на токени покажува колку сè потрошило, а режимот Без токени е за скромни недели. Потоа појадуваш, а во тоа агентите сè уште не можат да помогнат.","Најпрво, што AI-gile не е. Не е стартап, не се продава и никој не ги собира твоите податоци. Тоа е бесплатна табла што работи на твојот компјутер, без сметки, без следачи и без колачиња. Што е: едно уредно место за да ги видиш сите AI проекти одеднаш, со тим од агенти што ги работи картичките и ти што одлучуваш. Има и ноќна стража што ги подготвува картичките додека спиеш. Ги спојува сродните картички, ги поправа збунетите наслови и внимава колку скромен останува кодот. Зборува околу 120 јазици, од холандски и фламански до гусарски и клингонски. Пријателите можат да си праќаат пораки, приватно и шифрирано. Го изградија Rich и голем број трпеливи агенти, најмногу користејќи ја самата табла. Во затворена пред-алфа е, па на места е груба. Ако ти звучи забавно, прашај љубезно и можеби ќе влезеш рано."]}],"quips":{"1":"Еден збор. Храбро. Можеби премногу храбро.","3":"Три збора. Веќе поискрено од повеќето страници за производи.","8":"Осум зборови. Сè уште пократко од еден stand-up.","21":"Должините се story points, патем. Се разбира.","55":"Педесет и пет зборови. Додека го читаше ова, завршени се две картички.","144":"Ова е долгата. Нема 233. Агентите отидоа да спијат."}},"timeline":{"first-idea.name":"Првата идеја","first-idea.line":"Самиот прв разговор, пред да постои и еден ред код.","first-board.name":"Првата табла","first-board.line":"Табла што ја следи сопствената изградба: картички, колони, влечење, проекти.","team-roles.name":"Тим и улоги","team-roles.line":"Профили на агенти, шаблони за тимови, простори и кој што прави.","install.name":"Инсталација и изданија","install.line":"Зип што пријател може да го инсталира, самоажурирање, канали и враќање назад.","usage-saver.name":"Штедач на потрошувачка","usage-saver.line":"Мерење колку чинат извршувањата, скромен код, чување на твојот лимит.","friends.name":"Пријатели и споделување","friends.line":"Приватни пораки, шифриран релеј, покани, улоги и споделени проекти.","languages.name":"Јазици","languages.line":"Секој текст на екран во јазична датотека, прво холандски и фламански.","ai-tester.name":"AI тестер","ai-tester.line":"Тестер ја проверува секоја предавање прво и покажува што видел.","website.name":"Веб-страницата","website.line":"aigile.lol, најавата и оваа временска лента.","streaming.name":"Разговор и стриминг","streaming.line":"Discord, Twitch, OBS, режим за стримери, GIF-ови и емоџија.","no-ai.name":"Издание без AI","no-ai.line":"Табла за луѓе што пишуваат код без AI, и јавни табли.","night-watch.name":"Ноќна стража","night-watch.line":"Чувар и Scrum Master ги држат тимовите на задача додека спиеш.","p-more.name":"Сè друго","p-more.line":"Помали идеи што сè уште чекаат ред.","p-android.name":"Телефон и Android","p-android.line":"Стигни до таблата од телефон, па изворна Android апликација.","p-release.name":"Алфа и потоа","p-release.line":"Затворена алфа, живата страница, па бета.","p-languages.name":"Повеќе јазици","p-languages.line":"130 јазици и режим на потопување за оние што учат.","p-engines.name":"Повеќе AI мотори","p-engines.line":"Избери Claude, Codex, Gemini, Copilot или Cursor за секој агент.","p-pro.name":"Професионална пракса","p-pro.line":"Ознаки за ризик, порти за спојување, картички за инциденти и заштитни огради.","p-self.name":"Грижа за тебе","p-self.line":"Режим за уморни, потсетници за грижа за себе и 4:20.","p-servers.name":"Сервери и раст","p-servers.line":"Глобални поставки за сервери, улоги и планирање за раст.","p-livestream.name":"Додатоци за стриминг","p-livestream.line":"Twitch разговор, сопствени емоџија и јавен преглед во живо."},"words":{"button":"📖 Стручни термини","h":"📖 Објаснети зборови","intro":"Бесплатна обука на едноставен јазик: секој поим што ќе го сретнеш од првата идеја до услуга на која луѓето се потпираат, со агилна работа, изработка, безбедност и работа со AI по пат.","search":"Пребарај збор…","none":"Ниеден збор не одговара.","close":"Затвори","count":{"one":"{count} збор","other":"{count} зборови"},"groups":[{"id":"idea","name":"💡 Идеја и истражување"},{"id":"plan","name":"🗺️ Планирање на работата"},{"id":"agile","name":"🔁 Агилни начини на работа"},{"id":"build","name":"🛠️ Градење"},{"id":"test","name":"🧪 Тестирање и квалитет"},{"id":"change","name":"🔀 Безбедно менување"},{"id":"run","name":"🛎️ Водење на услуга"},{"id":"sec","name":"🔒 Безбедност и приватност"},{"id":"ai","name":"🤖 Работа со AI"},{"id":"money","name":"💰 Пари и лиценци"}],"list":[{"id":"discovery","g":"idea","word":"Истражување на потребите","text":"Почетна фаза во која откриваш кој проблем вреди да се реши и за кого, пред да почне изработката.","also":["фаза на истражување","discovery phase"]},{"id":"problemstmt","g":"idea","word":"Опис на проблемот","text":"Една или две реченици што кажуваат кој има проблем, каков е и зошто е важен, за сите да се стремат кон истото.","also":["описи на проблемот","problem statements"]},{"id":"user","g":"idea","word":"Корисник","text":"Човек што го користи она што го создаваш. Работата служи за неговите потреби.","also":["корисници","user","users"],"noTip":1},{"id":"stakeholder","g":"idea","word":"Засегната страна","text":"Секој кому му е важен исходот или врз кого тој влијае, како луѓето што плаќаат, го користат или го поддржуваат производот.","also":["засегнати страни","stakeholders"]},{"id":"persona","g":"idea","word":"Персона","text":"Измислен, но реалистичен човек што претставува еден вид корисници, за тимот да може да праша: „Дали ова би му било лесно на Сем?“","also":["персони","personas"]},{"id":"userresearch","g":"idea","word":"Истражување на корисниците","text":"Разговор со вистински луѓе и набљудување на нивната работа за да дознаеш што им треба, наместо да погодуваш.","also":["интервјуа со корисници","user interviews"]},{"id":"journey","g":"idea","word":"Корисничко патување","text":"Чекорите што ги поминува човек за да заврши нешто, од првото слушање за него до крајот, и надвор од твојот производ. Кога ќе ги нацрташ, гледаш каде заглавува.","also":["кориснички патувања","патување на клиентот","user journeys","customer journey"]},{"id":"painpoint","g":"idea","word":"Болна точка","text":"Нешто што денес ги нервира или забавува луѓето. Добрите производи ги отстрануваат болните точки.","also":["болни точки","pain points"]},{"id":"assumption","g":"idea","word":"Претпоставка","text":"Нешто во кое веруваш, но сè уште не е проверено. Кога ќе ги запишеш претпоставките, гледаш што треба прво да провериш.","also":["претпоставки","assumptions"],"noTip":1},{"id":"hypothesis","g":"idea","word":"Хипотеза","text":"Образложена претпоставка што планираш да ја провериш, со очекуван исход, на пример: „Луѓето ќе се регистрираат ако првиот месец е бесплатен.“","also":["хипотези","hypotheses"]},{"id":"experiment","g":"idea","word":"Експеримент","text":"Мала планирана проба за да дознаеш дали идејата функционира пред да вложиш многу во неа.","also":["експерименти","experiments"],"noTip":1},{"id":"poc","g":"idea","word":"Проверка на концепт (PoC)","text":"Брз, груб обид да се види дали идејата воопшто може да работи. Обично се отфрла штом ќе го добиеш одговорот.","also":["PoC","proof of concept","проверка на концепт"]},{"id":"prototype","g":"idea","word":"Прототип","text":"Ран модел на производот, често слики на кои може да се кликне, за да ја испробаш идејата со луѓе пред вистинската изработка.","also":["прототипи","prototypes"]},{"id":"wireframe","g":"idea","word":"Скица на екран","text":"Едноставна скица на екран што покажува каде стојат работите, без бои или вистинска содржина.","also":["скици на екрани","wireframes"]},{"id":"mockup","g":"idea","word":"Макета","text":"Детална слика на идниот екран со вистински бои и текст, но на која сè уште ништо не работи.","also":["макети","mockups","mock-up","mock-ups"]},{"id":"bizcase","g":"idea","word":"Деловно образложение","text":"Причините да се започне проект: колку чини, што носи или заштедува и кои се ризиците.","also":["деловни образложенија","business cases"]},{"id":"feasibility","g":"idea","word":"Изводливост","text":"Дали нешто навистина може да се изгради и одржува со времето, парите и вештините што ги имаш.","also":["изводливо"]},{"id":"outcome","g":"idea","word":"Исход","text":"Промената што ја сакаш за луѓето, како помалку пропуштени термини. Таа е поважна од тоа колку нешта ќе се изградат.","also":["исходи","outcomes"],"noTip":1},{"id":"output","g":"idea","word":"Изработен резултат","text":"Нешто што тимот го создава, како нов екран или извештај. Самото создавање не значи дека некому му помага.","also":["изработени резултати","outputs"],"noTip":1},{"id":"successmetric","g":"idea","word":"Мерило за успех","text":"Бројка што покажува дали работата ја постигнала целта, на пример повеќе луѓе што ја довршуваат нарачката.","also":["мерила за успех","success metrics"]},{"id":"kpi","g":"idea","word":"Клучен показател за успешност (KPI)","text":"Важна бројка што ја следиш за да видиш дали работите одат добро, како бројот на регистрации неделно.","also":["KPI","KPIs","key performance indicator","клучен показател"]},{"id":"okr","g":"idea","word":"Цели и клучни резултати (OKR)","text":"Начин на поставување цели: целта кажува што сакаш, а неколку клучни резултати се бројките што покажуваат дека е постигната.","also":["OKR","OKRs"]},{"id":"product","g":"plan","word":"Производ","text":"Нештото што се создава и одржува за корисниците, како апликација, веб-страница или алатка.","also":["производи","products"],"noTip":1},{"id":"vision","g":"plan","word":"Визија за производот","text":"Краток опис кому му помага производот и каде се движи долгорочно.","also":["изјава за визијата","vision statement"]},{"id":"po","g":"plan","word":"Сопственик на производот (PO)","text":"Човекот што одлучува што ќе се изработи и по кој редослед, за тимот секогаш да работи на најважното. Во AI-gile тоа си ти.","also":["PO","сопственици на производот","product owners"]},{"id":"pm","g":"plan","word":"Менаџер на производот (PM)","text":"Човекот што се грижи за насоката на производот: кои проблеми ги решава, за кого и зошто. PM може да значи и проектен менаџер, па провери на што се мисли.","also":["менаџери на производи","product managers"]},{"id":"projmgr","g":"plan","word":"Проектен менаџер","text":"Човекот што внимава проектот да се заврши навреме и во рамки на буџетот, следејќи кој што прави и до кога.","also":["проектни менаџери","project managers"]},{"id":"roadmap","g":"plan","word":"Патна мапа","text":"Приближен план за тоа што следува во наредните месеци, по редослед. Покажува насока, без точни датуми, и се менува со новите сознанија.","also":["патни мапи","roadmap","roadmaps"]},{"id":"milestone","g":"plan","word":"Пресвртница","text":"Момент во проектот што вреди да се означи, како „првата верзија е достапна“ или „100 корисници“.","also":["пресвртници","milestones"]},{"id":"mvp","g":"plan","word":"Минимално одржлив производ (MVP)","text":"Најмалата верзија на производот што сепак им е корисна на вистински луѓе, за рано да учиш од нив.","also":["MVP","MVPs","minimum viable product","минимално одржлив производ"]},{"id":"requirement","g":"plan","word":"Барање","text":"Нешто што готовиот производ мора да го прави или да го има како својство.","also":["барања за производот","requirements"],"noTip":1},{"id":"scope","g":"plan","word":"Опсег на работа","text":"Што е вклучено во работата и, исто толку важно, што не е.","also":["во опсег","надвор од опсег","in scope","out of scope"]},{"id":"scopecreep","g":"plan","word":"Неконтролирано ширење на опсегот","text":"Кога во работата постојано се додава нешто, без договор за дополнително време или трошоци, па никако да се заврши.","also":["ширење на функционалностите","feature creep"]},{"id":"feature","g":"plan","word":"Функционалност","text":"Едно нешто што производот може да го направи за луѓето, како повторно поставување лозинка.","also":["функционалности","features"],"noTip":1},{"id":"epic","g":"plan","word":"Епик","text":"Голем дел од работата што не може да се заврши одеднаш, па се дели на помали картички.","also":["епици","epics"]},{"id":"story","g":"plan","word":"Корисничка приказна","text":"Мал дел од работата опишан од гледна точка на корисникот: „Како купувач сакам да ја зачувам кошничката за да довршам подоцна.“ Отвора разговор за тоа што треба да се изработи.","also":["кориснички приказни","user stories"]},{"id":"ac","g":"plan","word":"Критериуми за прифаќање (AC)","text":"Проверки договорени пред почетокот на работата што картичката мора да ги помине за да се смета за завршена, како: „Кошничката останува и по одјавување и повторно најавување.“","also":["критериуми за прифаќање","acceptance criteria"]},{"id":"task","g":"plan","word":"Задача","text":"Една работа што треба да се заврши, често мал чекор од поголема корисничка приказна.","also":["задачи","tasks"],"noTip":1},{"id":"ticket","g":"plan","word":"Тикет","text":"Друг збор за картичка: една работа или барање што се следи од почеток до крај.","also":["тикети","tickets"]},{"id":"priority","g":"plan","word":"Приоритет","text":"Колку нешто е важно или итно во споредба со другите работи, за најважното да се прави прво.","also":["приоритети","priorities"],"noTip":1},{"id":"prioritise","g":"plan","word":"Одредување приоритети","text":"Подредување на работата според важноста. Чест начин е MoSCoW: мора да има, треба да има, може да има и нема да има овојпат.","also":["приоритизација","MoSCoW"]},{"id":"estimate","g":"plan","word":"Процена","text":"Најдобрата претпоставка за големината или траењето на работата. Тоа е претпоставка, а не ветување.","also":["процени","проценување","estimates","estimation"],"noTip":1},{"id":"storypoints","g":"plan","word":"Поени за приказни","text":"Начин да се процени големината на работата со споредување картички, како „околу двојно поголема“, наместо со часови. Не служат за споредување тимови.","also":["поен за приказна","story point"]},{"id":"tshirt","g":"plan","word":"Процена со големини на маици","text":"Проценување на работата како S, M, L или XL. Брзо е и доволно добро за почетно планирање.","also":["големини на маици","t-shirt sizes"]},{"id":"poker","g":"plan","word":"Покер за планирање","text":"Игра за проценување: сите истовремено покажуваат картичка со големина, а потоа оние со највисока и најниска процена објаснуваат зошто.","also":["Scrum poker","покер за планирање"]},{"id":"dependency","g":"plan","word":"Зависност","text":"Кога една работа не може да почне или да заврши додека тоа не го направи друга.","also":["зависности","dependencies"]},{"id":"blocker","g":"plan","word":"Пречка","text":"Сè што во моментот го запира напредокот, како неодговорено прашање или расипана алатка.","also":["пречки","blockers"]},{"id":"deadline","g":"plan","word":"Краен рок","text":"Датумот до кој нешто мора да биде завршено.","also":["крајни рокови","deadlines"],"noTip":1},{"id":"deliverable","g":"plan","word":"Резултат за предавање","text":"Нешто конкретно што се создава и предава со работата, како функционална страница или извештај.","also":["резултати за предавање","deliverables"]},{"id":"forecast","g":"plan","word":"Прогноза","text":"Предвидување што веројатно ќе се случи, како кога ќе заврши работата, врз основа на она што го знаеш досега.","also":["прогнози","forecasts"],"noTip":1},{"id":"metric","g":"plan","word":"Мерило","text":"Нешто што го мериш и следиш со текот на времето, како посети на страница или време потребно за поправка.","also":["мерила","metrics"]},{"id":"feedback","g":"plan","word":"Повратни информации","text":"Она што луѓето ти го кажуваат за работата, добро и лошо. Нивното рано и често добивање е во сржта на агилната работа.","noTip":1},{"id":"backlog","g":"agile","word":"Backlog","text":"Листа на чекање со идеи и работа што сè уште не е планирана, со најважното на врвот. Ништо од неа не се работи додека не премине во „За работа“."},{"id":"sprint","g":"agile","word":"Спринт","text":"Краток, однапред одреден работен период, често една или две недели и никогаш повеќе од месец, со цел и договорен збир картички за завршување.","also":["спринтови","sprints"]},{"id":"standup","g":"agile","word":"Стенд-ап","text":"Краток дневен состанок: што направил секој член, што прави следно и што го запира. Во Scrum се нарекува дневен Scrum.","also":["standup","stand-ups","daily scrum","daily stand-up","дневен состанок"]},{"id":"kanban","g":"agile","word":"Kanban","text":"Начин на работа во кој картичките се движат низ колоните на таблата, како „За работа“, „Во тек“ и „Готово“, а тимот ја ограничува истовремената работа за таа непречено да тече."},{"id":"wip","g":"agile","word":"WIP лимит","text":"WIP е кратенка за work in progress, односно работа во тек. WIP лимитот е најголемиот број картички што една колона треба да ги држи одеднаш, за тимот да ги завршува работите пред да почне нови.","also":["WIP"]},{"id":"dod","g":"agile","word":"Дефиниција за Завршено","text":"Кратката листа на тимот за тоа што значи „завршено“, на пример тестирано и објаснето, пред картичката да ти се предаде. Нејзиниот близнак, Дефиниција за Подготвено, кажува кога картичката е доволно јасна за да се почне.","also":["Definition of Ready","DoD","DoR","дефиниција за подготвеност","дефиниција за завршеност"]},{"id":"retro","g":"agile","word":"Ретро","text":"Редовен поглед наназад на тоа како работи тимот, за да се договорат едно или две подобрувања за следниот пат. Скратено од ретроспектива. Во AI-gile ретрото предлага промена во начинот на работа на тимот, а ти велиш Go или Уште не.","also":["ретроспектива","ретроспективи","ретроспективата","ретроа"]},{"id":"swarm","g":"agile","word":"Рој","text":"Сите на помош: повеќе луѓе оставаат друга работа за заедно да решат една итна работа до крај. Во AI-gile сите тимови помагаат на еден проект, додека другите проекти чекаат.","also":["ројот","ројување"]},{"id":"scrummaster","g":"agile","word":"Scrum Master","text":"Во Scrum, човекот што му помага на тимот да работи добро: отстранува пречки, ги држи состаноците на вистинскиот пат и развива добри навики, без да наредува. Во AI-gile, Lead Scrum Master забележува заглавени картички, ги поттикнува тимовите и те потсетува што чека, низ сите проекти.","also":["Lead Scrum Master"]},{"id":"agile","g":"agile","word":"Agile (агилна работа)","text":"Работа во мали чекори: изработуваш малку, често покажуваш вистински резултати, учиш од мислењата на луѓето и го менуваш планот по пат, наместо сè да испланираш однапред.","also":["Agile development","agile ways of working","агилен развој"]},{"id":"manifesto","g":"agile","word":"Агилен манифест","text":"Кратка изјава напишана во 2001 година од создавачи на софтвер. Ги става луѓето, функционалните резултати, блиската соработка со клиентите и реагирањето на промени пред тешките планови и папирологијата.","also":["Manifesto for Agile Software Development","Манифест за агилен развој на софтвер"]},{"id":"waterfall","g":"agile","word":"Водопаден модел","text":"Постар начин на работа: прво се планира сè, потоа се изработува сè, па се тестира сè, фаза по фаза. Доцните промени се тешки и скапи.","also":["waterfall model","водопаден модел"]},{"id":"iteration","g":"agile","word":"Итерација","text":"Еден круг на изработка, проверка и подобрување. Агилната работа е низа вакви кругови, а спринтот е еден вид.","also":["итерации","iterations"]},{"id":"increment","g":"agile","word":"Прираст на производот","text":"Нов функционален дел додаден во производот во еден спринт или круг работа, кој се вклопува со постојното.","also":["прирасти","increments"]},{"id":"scrum","g":"agile","word":"Scrum","text":"Популарен агилен начин на работа: мал тим работи во кратки спринтови кон цел, со утврдени улоги и неколку редовни состаноци за планирање, проверка и подобрување."},{"id":"scrumteam","g":"agile","word":"Scrum тим","text":"Малата група што ја извршува работата во Scrum: сопственик на производот, Scrum Master и програмерите.","also":["Scrum тимови","Scrum teams"]},{"id":"ceremonies","g":"agile","word":"Scrum настани","text":"Редовните состаноци во Scrum: планирање на спринтот, дневен Scrum, преглед на спринтот и ретрото. Многумина ги нарекуваат церемонии.","also":["церемонии","ceremonies","Scrum ceremonies"]},{"id":"sprintplan","g":"agile","word":"Планирање на спринтот","text":"Состанок на почетокот на спринтот на кој тимот се договара зошто е важен, кои картички ќе ги преземе и како ќе почне.","also":["состанок за планирање","planning meeting"]},{"id":"sprintgoal","g":"agile","word":"Цел на спринтот","text":"Една реченица што ја кажува целта на спринтот. Малите задачи може да се менуваат, сè додека целта се постигнува.","also":["цели на спринтот","sprint goals"]},{"id":"sprintbacklog","g":"agile","word":"Backlog на спринтот","text":"Картичките избрани за тековниот спринт, со планот на тимот како да ги заврши.","also":["sprint backlogs","sprint backlog"]},{"id":"productbacklog","g":"agile","word":"Backlog на производот","text":"Целосна подредена листа на сè што би можело да се изработи за производот, со најважното на врвот. Се менува со новите сознанија.","also":["product backlogs","product backlog"]},{"id":"productgoal","g":"agile","word":"Цел на производот","text":"Поголемиот резултат кон кој се стреми производот, што му помага на тимот да избере што да прави понатаму.","also":["цели на производот","product goals"]},{"id":"refinement","g":"agile","word":"Дотерување на backlog-от","text":"Редовно прегледување на backlog-от за картичките да се средат, поделат, подредат и дообјаснат, за да бидат подготвени за работа. Се нарекува и backlog grooming.","also":["backlog grooming","refinement","дотерување на backlog-от"]},{"id":"sprintreview","g":"agile","word":"Преглед на спринтот","text":"Состанок на крајот на спринтот на кој тимот покажува што завршил и слуша мислења за да одлучи што следува.","also":["прегледи на спринтот","sprint reviews"]},{"id":"demo","g":"agile","word":"Демонстрација","text":"Прикажување во живо како работи завршеното пред луѓето што го побарале.","also":["демонстрации","demos"],"noTip":1},{"id":"timebox","g":"agile","word":"Временско ограничување","text":"Однапред одредено време за нешто. Кога ќе истече, запираш, дури и ако не е сè завршено.","also":["временски ограничено","timeboxed","timeboxes"]},{"id":"velocity","g":"agile","word":"Темпо на тимот","text":"Колку работа обично завршува тимот во спринт, за да планира колку да преземе следниот пат. Не е оценка за тоа колку напорно работат луѓето.","also":["тимско темпо","team velocity"]},{"id":"capacity","g":"agile","word":"Капацитет","text":"Колку работа може да преземе тимот во одреден период, кога ќе се земат предвид одморите и другите обврски.","noTip":1},{"id":"burndown","g":"agile","word":"Графикон на преостаната работа","text":"Графикон што покажува како преостанатата работа во спринтот се намалува секој ден. Ако линијата е рамна, нешто е заглавено.","also":["burndown","burn-down chart"]},{"id":"burnup","g":"agile","word":"Графикон на завршена работа","text":"Графикон на завршената работа што расте со времето, покрај вкупно планираната, за да видиш кога ќе стигнеш до целта.","also":["burnup","burn-up chart"]},{"id":"kanbanboard","g":"agile","word":"Kanban табла","text":"Самата табла: посебна колона за секоја фаза на работата, а картичките се движат од една во друга.","also":["Kanban табли","Kanban boards"]},{"id":"pullsys","g":"agile","word":"Систем на повлекување работа","text":"Начин на работа во кој нова задача почнува само кога некој има простор да ја преземе, наместо да се додава на веќе преполн распоред.","also":["pull-based","повлекување работа"]},{"id":"flow","g":"agile","word":"Тек на работата","text":"Колку непречено се движи работата низ таблата. Добар тек значи дека картичките се движат наместо да се натрупуваат.","also":["flow of work","тек на работа"],"noTip":1},{"id":"leadtime","g":"agile","word":"Време од барање до завршување","text":"Колку време минува од нечие барање до неговото завршување.","also":["lead times","време на исполнување"]},{"id":"cycletime","g":"agile","word":"Времетраење на циклусот","text":"Колку време минува од вистинскиот почеток на работата на картичка до нејзиното завршување.","also":["cycle times","време на циклус"]},{"id":"throughput","g":"agile","word":"Пропусност","text":"Колку картички се завршуваат за една недела или друг одреден период.","also":["throughput rate","стапка на завршување"]},{"id":"bottleneck","g":"agile","word":"Тесно грло","text":"Фаза во која работата се натрупува и го забавува сето она зад неа, како тесниот врат на шише.","also":["тесни грла","bottlenecks"]},{"id":"swimlane","g":"agile","word":"Хоризонтална лента","text":"Ред низ таблата што групира картички од ист вид, како итна работа или картички на еден тим.","also":["хоризонтални ленти","swimlanes","swim lane"]},{"id":"lean","g":"agile","word":"Lean","text":"Начин на работа што го намалува залудното трошење ресурси, односно сè што не му помага на клиентот, и ја одржува работата во тек."},{"id":"waste","g":"agile","word":"Залудно трошење ресурси","text":"Во Lean, сè што бара труд, но не му помага на клиентот, како чекање, повторна изработка или создавање нешта што никој не ги користи.","noTip":1},{"id":"kaizen","g":"agile","word":"Постојано подобрување","text":"Постојано подобрување преку мали редовни промени, со проверка дали помогнале. Ретрата се еден начин за тоа. Се нарекува и каизен.","also":["kaizen","каизен"]},{"id":"selforg","g":"agile","word":"Самоорганизиран тим","text":"Тим што самиот одлучува како да ја заврши работата, наместо да добива упатства за секој чекор.","also":["самоорганизиран","самоуправуван тим","self-organising","self-managing team"]},{"id":"crossfunc","g":"agile","word":"Тим со различни вештини","text":"Тим што ги има сите вештини сам да ја заврши работата, како дизајн, изработка и тестирање.","also":["cross-functional","меѓуфункционален тим"]},{"id":"spike","g":"agile","word":"Spike (кратко истражување)","text":"Кратко истражување со временско ограничување за да се одговори на прашање пред да се започне вистинската работа.","also":["spikes","spike"]},{"id":"rework","g":"agile","word":"Повторна изработка","text":"Повторно извршување на работата бидејќи првиот пат не била направена како што треба.","also":["повторно изработено","reworked"]},{"id":"safe","g":"agile","word":"Agile во голем обем (SAFe)","text":"Начини за примена на Agile во многу тимови во голема организација. SAFe (Scaled Agile Framework) е еден добро познат пример.","also":["scaled Agile","агилна работа во голем обем"]},{"id":"repo","g":"build","word":"Репо","text":"Папката со кодот на проектот и целосната историја на комити. Може да биде на твојот компјутер, на GitHub или на двете места.","also":["репозиториум","repository"]},{"id":"branch","g":"build","word":"Бранч","text":"Посебна линија на работа во кодот, за да се прават промени без да се допира главната верзија.","also":["бранчови","branches"]},{"id":"commit","g":"build","word":"Комит","text":"Зачуван снимок на кодот, со кратка белешка што се променило. Секогаш можеш да се вратиш на него.","also":["комити","commits"]},{"id":"push","g":"build","word":"Push","text":"Испраќање на зачуваните снимки (комити) од овој компјутер во заедничката копија на интернет, како GitHub, за да бидат резервирани и достапни за другите."},{"id":"merge","g":"build","word":"Merge","text":"Спојување на промените од еден бранч во друг, обично назад во главната верзија."},{"id":"pr","g":"build","word":"Pull request","text":"Барање промените од еден бранч да се проверат и спојат во главната верзија. Некои страници го нарекуваат merge request.","also":["PR","PRs","merge request","барање за спојување"]},{"id":"refactor","g":"build","word":"Рефакторирање","text":"Средување на кодот без менување на она што го прави: помали датотеки, појасни имиња, помалку повторување."},{"id":"bug","g":"build","word":"Баг","text":"Нешто што не работи како што треба.","also":["багови","bugs"]},{"id":"peerreview","g":"build","word":"Колегијален преглед","text":"Уште еден пар очи: некој друг освен авторот ја проверува работата пред да стигне до тебе, за да поминат помалку грешки. Во AI-gile друг AI ја проверува секоја картичка.","also":["колегијалниот преглед","преглед на код"]},{"id":"code","g":"build","word":"Код","text":"Напишаните упатства што му кажуваат на компјутерот што да прави. Се нарекува и изворен код.","also":["изворен код","source code"],"noTip":1},{"id":"proglang","g":"build","word":"Програмски јазик","text":"Јазик за пишување код, како JavaScript, Python или Java. Различни јазици одговараат на различни задачи.","also":["програмски јазици","programming languages"]},{"id":"developer","g":"build","word":"Програмер (dev)","text":"Човек што пишува и менува код. Се нарекува и развивач или софтверски инженер.","also":["програмери","развивач","развивачи","developer","developers","programmer","programmers","software engineer"]},{"id":"software","g":"build","word":"Софтвер","text":"Програмите што работат на компјутери и телефони, за разлика од самите уреди, односно хардверот.","noTip":1},{"id":"app","g":"build","word":"Апликација","text":"Програма што луѓето ја користат за да завршат нешто на телефон, компјутер или во веб-прелистувач.","also":["апликации","apps","application","applications"],"noTip":1},{"id":"webapp","g":"build","word":"Веб-апликација","text":"Апликација што работи во веб-прелистувач, па нема ништо за инсталирање.","also":["веб-апликации","web apps","web application"]},{"id":"frontend","g":"build","word":"Front end (преден дел)","text":"Делот од апликацијата што го гледаш и на кој кликаш: екраните, копчињата и текстот, често во прелистувачот.","also":["front-end","frontend","кориснички дел"]},{"id":"backend","g":"build","word":"Back end (заднински дел)","text":"Делот зад сцената што ги чува податоците и ја извршува работата кога ќе кликнеш, како проверка на лозинката.","also":["back-end","backend","серверски дел"]},{"id":"fullstack","g":"build","word":"Full stack","text":"Работа и на предниот и на заднинскиот дел од апликацијата.","also":["full-stack","целосен развој"]},{"id":"ui","g":"build","word":"Кориснички интерфејс (UI)","text":"Она што човек го гледа и користи на екранот: распоред, копчиња, менија и текст.","also":["UI","user interface","кориснички интерфејс"]},{"id":"ux","g":"build","word":"Корисничко искуство (UX)","text":"Какво е чувството кога користиш нешто: лесно, јасно и пријатно или збунувачко и бавно.","also":["UX","user experience","корисничко искуство"]},{"id":"accessibility","g":"build","word":"Пристапност (a11y)","text":"Правење нешта што можат да ги користат сите, вклучувајќи луѓе со слаб вид, луѓе што не користат глувче или користат читач на екран.","also":["a11y","пристапност"]},{"id":"responsive","g":"build","word":"Приспособлив дизајн","text":"Правење страници што добро се вклопуваат и работат на секоја големина на екран, од телефон до голем монитор.","also":["респонзивен дизајн"]},{"id":"designsys","g":"build","word":"Дизајн-систем","text":"Заеднички збир на бои, фонтови, копчиња и правила, за секој екран да изгледа и да се однесува доследно.","also":["дизајн-системи","design systems"]},{"id":"architecture","g":"build","word":"Архитектура","text":"Општата поставеност на системот: кои се главните делови и како комуницираат меѓусебно."},{"id":"database","g":"build","word":"База на податоци (DB)","text":"Организирана збирка информации, како многу моќна табела што апликацијата може да ја чита и менува.","also":["база на податоци","бази на податоци","database","databases","DB"]},{"id":"schema","g":"build","word":"Шема на базата на податоци","text":"Распоредот на базата: кои табели со информации ги има и што се чува во секоја.","also":["schema","шема"]},{"id":"sql","g":"build","word":"SQL","text":"Кратенка за структуриран јазик за пребарување: јазик со кој од многу бази се бараат информации или се менуваат.","also":["Structured Query Language","структуриран јазик за пребарување"]},{"id":"data","g":"build","word":"Податоци","text":"Информации што ги чува компјутер, како имиња, нарачки или поставки.","also":["збирка податоци","збирки податоци","dataset","datasets"],"noTip":1},{"id":"server","g":"build","word":"Сервер","text":"Компјутер што е постојано вклучен и одговара на барања од други компјутери, како испраќање веб-страница кога ја посетуваш.","also":["сервери","servers"]},{"id":"client","g":"build","word":"Клиент","text":"Страната што бара нешто, обично твојот прелистувач или апликација, која комуницира со сервер. Во деловниот свет значи и купувач на услуга.","also":["клиенти","clients"],"noTip":1},{"id":"api","g":"build","word":"API","text":"Кратенка за програмски интерфејс: утврден список на барања што една програма може да ѝ ги испрати на друга, како барање денешна временска прогноза.","also":["APIs","application programming interface","програмски интерфејс"]},{"id":"endpoint","g":"build","word":"Пристапна точка","text":"Една ставка од списокот на API: веб-адреса на која програма се обраќа за да добие или испрати нешто.","also":["пристапни точки","endpoints"]},{"id":"integration","g":"build","word":"Интеграција","text":"Поврзување два система за да работат заедно, како продавница што испраќа нарачки во сметководствена програма.","also":["интеграции","integrations"]},{"id":"webhook","g":"build","word":"Webhook","text":"Порака што еден систем сам ја испраќа до друг штом нешто ќе се случи, како „примена уплата“.","also":["webhooks","вебхук"]},{"id":"library","g":"build","word":"Библиотека","text":"Готов код напишан од некој друг што можеш повторно да го употребиш, наместо да го пишуваш од почеток.","also":["библиотеки","libraries"],"noTip":1},{"id":"framework","g":"build","word":"Развојна рамка","text":"Готова структура за градење апликација што одредува голем дел од распоредот на кодот, како конструкција на куќа што ја пополнуваш.","also":["развојни рамки","frameworks"]},{"id":"sdk","g":"build","word":"Комплет за развој на софтвер (SDK)","text":"Збир од алатки, код и примери за создавање софтвер за одредена платформа или услуга.","also":["SDK","SDKs"]},{"id":"softdep","g":"build","word":"Софтверска зависност","text":"Библиотека или алатка што му е потребна на твојот код за да работи. Редовното ажурирање е важно за безбедноста.","also":["софтверски зависности","software dependencies"]},{"id":"package","g":"build","word":"Пакет","text":"Збир од готов код што можеш да го инсталираш и користиш во проект.","also":["пакети","packages"],"noTip":1},{"id":"pkgmgr","g":"build","word":"Управувач со пакети","text":"Алатка што ги презема и ажурира пакетите од кои зависи твојот код. npm е чест пример.","also":["управувачи со пакети","package managers","npm"]},{"id":"git","g":"build","word":"Git","text":"Најкористената алатка за чување на историјата на промените во кодот, во облик на комити и бранчови."},{"id":"github","g":"build","word":"GitHub","text":"Веб-страница што чува Git репоа на интернет, за тимовите да споделуваат код, да прегледуваат промени и да ја следат работата."},{"id":"vcs","g":"build","word":"Контрола на верзии","text":"Чување целосна историја на секоја промена во датотеките, за да видиш кој што сменил и да се вратиш назад ако треба. Git го прави тоа.","also":["source control","version control system","систем за контрола на верзии"]},{"id":"clone","g":"build","word":"Клонирање","text":"Правење сопствена целосна копија од репо, со неговата историја, на твојот компјутер.","also":["клонирано","cloned","cloning"]},{"id":"pull","g":"build","word":"Pull","text":"Преземање на најновите комити од заедничката копија (на пример GitHub) на твојот компјутер. Спротивно од push.","also":["git pull","пул"],"noTip":1},{"id":"mainbranch","g":"build","word":"Главен бранч","text":"Официјалната верзија на кодот од која сите ја започнуваат работата, често наречена main или master.","also":["master branch","главна гранка","главен бранч"]},{"id":"conflict","g":"build","word":"Merge конфликт","text":"Кога две промени ги менуваат истите редови на различни начини, па компјутерот не може да ги спои и човек мора да избере.","also":["merge conflicts","merge конфликти","конфликт при спојување"]},{"id":"diff","g":"build","word":"Diff (преглед на разлики)","text":"Приказ што точно покажува што се сменило меѓу две верзии: додадените и отстранетите редови.","also":["diffs","диф"]},{"id":"fork","g":"build","word":"Fork","text":"Твоја копија од туѓо репо што можеш да ја менуваш без да влијаеш врз оригиналот.","also":["forks","forked","форк"]},{"id":"script","g":"build","word":"Скрипта","text":"Кратка програма што сама извршува една задача, како средување датотеки или стартување апликација.","also":["скрипти","scripts"],"noTip":1},{"id":"build","g":"build","word":"Изградба","text":"Претворање на кодот во нешто подготвено за извршување, или самиот готов резултат.","also":["изградени верзии","builds"],"noTip":1},{"id":"compile","g":"build","word":"Компајлирање","text":"Преведување на кодот напишан од луѓе во облик што компјутерот може директно да го изврши.","also":["компајлирано","компајлер","compiler"]},{"id":"cli","g":"build","word":"Командна линија (CLI)","text":"Текстуален прозорец во кој пишуваш наредби за компјутерот наместо да кликаш. Се нарекува и терминал.","also":["command line","command-line","CLI","terminal","терминал"]},{"id":"config","g":"build","word":"Конфигурација (config)","text":"Поставките што одредуваат како се однесува софтверот, чувани одделно од кодот за лесно да се менуваат.","also":["config","configuration","конфигурации"],"noTip":1},{"id":"envvar","g":"build","word":"Променлива на околината","text":"Поставка што ѝ се предава на програма при стартување, често за адреси или лозинки за да не се запишуваат во кодот.","also":["променливи на околината","environment variables","env var"]},{"id":"debugging","g":"build","word":"Дебагирање","text":"Барање на причината зошто нешто не работи и нејзино поправање.","also":["debug","debugged","дебагира","отстранување грешки"]},{"id":"pairing","g":"build","word":"Програмирање во пар","text":"Двајца луѓе (или човек и AI) работат заедно на ист код: еден пишува, другиот проверува.","also":["pairing","работа во пар"]},{"id":"docs","g":"build","word":"Документација","text":"Напишани објаснувања за тоа како нешто работи или како се користи.","also":["documentation","docs","документација"],"noTip":1},{"id":"readme","g":"build","word":"README","text":"Првата датотека што треба да ја прочиташ во репо: што е проектот и како да го стартуваш.","also":["READMEs"]},{"id":"legacy","g":"build","word":"Наследен систем","text":"Постар систем што сè уште се користи, но тешко се менува, често бидејќи малкумина сè уште го разбираат.","also":["наследени системи","legacy systems","legacy code"]},{"id":"techdebt","g":"build","word":"Технички долг","text":"Кратенки во работата што штедат време сега, но ги забавуваат идните промени, како заем што собира камата. Рефакторирањето го намалува.","also":["tech debt","технички долг"]},{"id":"test","g":"test","word":"Тест","text":"Проверка дали нешто работи како што треба. Некои тестови компјутерот ги извршува сам при секоја промена на кодот, а други се твоето испробување завршена картичка пред да ја прифатиш.","also":["тестови","tests"],"noTip":1},{"id":"qa","g":"test","word":"QA","text":"Кратенка за обезбедување квалитет: сè што се прави за работата да биде исправна пред пуштање во употреба. Во AI-gile тоа се автоматските проверки: кога QA е црвено, нешто не успеало и не може да се пушти додека не се поправи.","also":["проверки на квалитет","проверка на квалитет"]},{"id":"testpile","g":"test","word":"Куп за тестирање","text":"Завршените картички што чекаат да ги пробаш, една по друга. Прифати една или врати ја со белешка, и доаѓа следната.","also":["купови за тестирање","купот за тестирање"]},{"id":"autotest","g":"test","word":"Автоматизиран тест","text":"Проверка што компјутерот ја извршува сам секогаш кога кодот се менува, за рано да ги открие грешките.","also":["автоматизирани тестови","автоматски тестови","automated tests","automatic tests"]},{"id":"manualtest","g":"test","word":"Рачен тест","text":"Човек рачно ја испробува изработката за да види дали се однесува како што треба.","also":["рачни тестови","рачно тестирање","manual tests","manual testing"]},{"id":"unittest","g":"test","word":"Единичен тест","text":"Мала автоматска проверка на едно мало парче код само по себе.","also":["единични тестови","unit tests"]},{"id":"integtest","g":"test","word":"Интеграциски тест","text":"Проверка дали неколку делови правилно работат заедно, а не само секој одделно.","also":["интеграциски тестови","integration tests"]},{"id":"endtoend","g":"test","word":"Тест од почеток до крај (E2E)","text":"Тест што се однесува како вистински корисник од почеток до крај, како регистрирање, купување и плаќање.","also":["E2E","end-to-end tests","тестови од почеток до крај"]},{"id":"uat","g":"test","word":"Корисничко тестирање за прифаќање (UAT)","text":"Луѓето што ја побарале работата сами ја испробуваат и кажуваат дали го прави она што им треба. Купот за тестирање во AI-gile е неговата верзија на ова.","also":["UAT","acceptance testing","тестирање за прифаќање"]},{"id":"regression","g":"test","word":"Регресија","text":"Нешто што работело, но се расипало по промена. Регресивните тестови проверуваат дали старите работи сè уште работат.","also":["регресии","regression test","regression tests","regression testing","регресивно тестирање"]},{"id":"smoke","g":"test","word":"Smoke тест","text":"Многу брза проверка дали главните работи воопшто работат, на пример веднаш по пуштање промена. Ако не успее, застани и провери.","also":["smoke tests","smoke тестови"]},{"id":"exploratory","g":"test","word":"Истражувачко тестирање","text":"Слободно испробување на производот на различни начини, за да се најдат проблеми што планираните проверки би ги пропуштиле.","also":["exploratory test","exploratory tests","истражувачки тестови"]},{"id":"testcase","g":"test","word":"Тест-случај","text":"Едно запишано сценарио за испробување: чекорите и она што треба да се случи.","also":["тест-случаи","test cases"]},{"id":"coverage","g":"test","word":"Покриеност со тестови","text":"Колкав дел од кодот се проверува со автоматски тестови. Поголема покриеност обично е побезбедна, но сама по себе не докажува дека сè работи добро.","also":["code coverage","покриеност на кодот"]},{"id":"testdata","g":"test","word":"Тест-податоци","text":"Измислени примерни информации за тестирање, за да не се откријат приватните податоци на вистински луѓе.","also":["test fixtures","примерни податоци"]},{"id":"edgecase","g":"test","word":"Граничен случај","text":"Необична ситуација на границите, како празен формулар или име со апостроф, каде што работите често се расипуваат.","also":["гранични случаи","edge cases"]},{"id":"happypath","g":"test","word":"Успешно сценарио","text":"Вообичаениот пат кога сè оди како што треба. Доброто тестирање ги пробува и неуспешните сценарија."},{"id":"perftest","g":"test","word":"Тестирање на перформанси","text":"Проверка колку брзо работи нешто и како се справува со оптоварување.","also":["performance test","performance tests","тестови на перформанси"]},{"id":"loadtest","g":"test","word":"Тестирање на оптоварување","text":"Проверка како се справува системот кога многу луѓе го користат истовремено.","also":["load test","load tests","тестови на оптоварување"]},{"id":"sectest","g":"test","word":"Безбедносно тестирање","text":"Барање слабости што би овозможиле злоупотреба на системот или гледање информации без дозвола.","also":["security test","security tests","безбедносни тестови"]},{"id":"accesstest","g":"test","word":"Тестирање на пристапноста","text":"Проверка дали луѓе со различни способности можат да го користат производот, вклучувајќи со читач на екран или само со тастатура.","also":["accessibility test","тест за пристапност"]},{"id":"linting","g":"test","word":"Linting (проверка на кодот)","text":"Автоматска проверка што открива веројатни грешки и неуреден стил во кодот, како правописна проверка за програми.","also":["linter","lint","линтер"]},{"id":"static","g":"test","word":"Статичка анализа","text":"Автоматско читање на кодот за да се најдат проблеми без тој да се извршува.","also":["static code analysis","статичка анализа на кодот"]},{"id":"flaky","g":"test","word":"Нестабилен тест","text":"Тест што понекогаш успева, а понекогаш не, без јасна причина, па не може целосно да му се верува.","also":["нестабилни тестови","flaky tests"]},{"id":"repro","g":"test","word":"Повторување на грешката","text":"Намерно предизвикување на истата грешка со истите чекори за да се проучи и поправи. Запишувањето на чекорите е најкорисниот дел од пријавата за грешка.","also":["repro","reproduce","steps to reproduce","чекори за повторување"]},{"id":"severity","g":"test","word":"Сериозност","text":"Колку е лошо влијанието на проблемот, од мала непријатност до целосен прекин на работата.","also":["severity level","ниво на сериозност"]},{"id":"deploy","g":"change","word":"Деплој","text":"Копирање нова верзија на софтверот на компјутерите што го извршуваат, како тест-копија или услугата во живо."},{"id":"release","g":"change","word":"Издание","text":"Именуван пакет завршена работа што оди во живо заедно, со кратки белешки за тоа што се сменило. 🚀 Издања ги пишува белешките од готовите картички.","also":["изданија","изданието","изданија","издањата","издања"]},{"id":"rollback","g":"change","word":"Враќање назад","text":"Враќање на последната исправна верзија кога новата создава проблеми. Во AI-gile, „Врати назад“ ги собира чекорите за поништување запишани кај секоја промена во една контролна листа.","also":["врати назад","вратено назад","враќањето назад","rollback"]},{"id":"live","g":"change","word":"Во живо","text":"Вистинската верзија што луѓето ја користат, наспроти копија за пробување. Програмерите ја викаат и продукција.","also":["продукција","продукцијата"],"noTip":1},{"id":"change","g":"change","word":"Промена","text":"Планирана промена на нешто на што луѓето се потпираат, однапред запишана: што, зошто, ризикот, кога и како да се врати. Започни со 🔀 Поднеси промена.","also":["промени","промената","промените","барање за промена","барања за промена"],"noTip":1},{"id":"risk","g":"change","word":"Ризик","text":"Нешто што може да тргне наопаку, оценето според тоа колку е веројатно и колку лошо би било. ⚠️ Ризици ги чува на една листа, со највисоката оценка прва, секој со датум кога повторно да се погледне.","also":["ризици","ризикот","ризиците","регистар на ризици"]},{"id":"chgwin","g":"change","word":"Прозорец за промени","text":"Времињата кога промените смеат да одат во живо, на пример мирна вторник вечер. Надвор од прозорецот картичка за промена не може да се заврши, освен ако не е итна.","also":["прозорци за промени","прозорецот за промени","прозорец"]},{"id":"gonogo","g":"change","word":"Go / no go","text":"Последна проверка непосредно пред промената да оди во живо: секој што треба да одобри вели Go или No go. Се продолжува само кога сите ќе кажат Go.","also":["go/no go","go-no-go"]},{"id":"approval","g":"change","word":"Одобрување","text":"Чекање на „да“ пред работата да почне. Картичка што ја поднесува пријател, или промена, чека во ✅ Одобрувања додека не ја одобриш или одбиеш.","also":["одобрувања","одобрувањето","одобрувањата"]},{"id":"quiettime","g":"change","word":"Тивок период","text":"Период, како за време на пренос во живо, демонстрација или преку ноќ, кога ништо не се пушта во употреба. Тимовите продолжуваат со работа и тестирање, но пуштањето чека да заврши; на други места ова се нарекува замрзнување на промените.","also":["тивки периоди","тивкиот период","замрзнување на промени"]},{"id":"devops","g":"change","word":"DevOps","text":"Начин на работа во кој луѓето што го создаваат софтверот и оние што го одржуваат работат како еден тим, со многу автоматизација, за промените често и безбедно да стигнуваат до корисниците."},{"id":"cicd","g":"change","word":"CI/CD (постојана интеграција и испорака)","text":"Промените на сите често се спојуваат во главната верзија и секојпат автоматски се проверуваат (постојана интеграција), па софтверот е секогаш подготвен да оди во живо со притискање копче (постојана испорака).","also":["CI/CD","CI","CD","continuous integration","continuous delivery","постојана интеграција","постојана испорака"]},{"id":"contdeploy","g":"change","word":"Постојан деплој","text":"Чекор подалеку од постојаната испорака: секоја промена што ги поминува проверките сама оди во живо, без притискање копче.","also":["continuous deployments","continuous deployment","постојан деплој"]},{"id":"pipeline","g":"change","word":"Pipeline (низа автоматски чекори)","text":"Автоматската низа чекори низ кои поминува промената на патот до живо, како изградба, тестирање, па деплој.","also":["pipelines","пајплајн"]},{"id":"environment","g":"change","word":"Околина","text":"Една одделна копија од системот за одредена цел, како за развој, за тестирање или за вистинска употреба.","also":["околини","environments"],"noTip":1},{"id":"devenv","g":"change","word":"Развојна околина","text":"Копијата во која работи програмерот, често на сопствениот компјутер, каде што ништо не е страшно ако нешто се расипе.","also":["dev environment","околина за развој"]},{"id":"testenv","g":"change","word":"Тест-околина","text":"Одделна копија од системот само за тестирање, за вистинската услуга да остане недопрена.","also":["test environments","околини за тестирање"]},{"id":"staging","g":"change","word":"Предпродукциска околина","text":"Последна копија поставена како вистинскиот систем, за завршна проверка пред пуштање на промената.","also":["staging environment","предпродукциска околина"]},{"id":"artifact","g":"change","word":"Артефакт од изградба","text":"Датотеката или пакетот создаден при изградба, подготвен за чување, проверка или пуштање во употреба.","also":["build artifacts","артефакти од изградба"]},{"id":"hotfix","g":"change","word":"Итна поправка","text":"Итна поправка пуштена брзо, надвор од редовниот план, бидејќи нешто важно е расипано.","also":["hotfixes","итни поправки"]},{"id":"patch","g":"change","word":"Закрпа","text":"Мало ажурирање што поправа грешка или затвора безбедносна дупка. Важно е безбедносните закрпи да се применуваат брзо.","also":["patches","security patch","security patches","безбедносни закрпи"]},{"id":"version","g":"change","word":"Број на верзија","text":"Ознака како 2.4.1 што кажува кое издание го имаш. Често првиот број се менува за големи промени, а последниот за мали поправки.","also":["version numbers","semantic versioning","броеви на верзии","семантичко верзионирање"]},{"id":"relnotes","g":"change","word":"Белешки за изданието","text":"Кратка и јасна листа на промените во изданието за корисниците, вклучувајќи поправки и познати ограничувања. Се нарекува и дневник на промени.","also":["changelog","change log","дневник на промени"]},{"id":"flag","g":"change","word":"Прекинувач за функционалност","text":"Прекинувач за вклучување и исклучување функционалност. Новата работа може да се пушти скриена и да се вклучи или исклучи без ново издание.","also":["feature flags","feature toggle","feature toggles","прекинувачи за функционалности"]},{"id":"rollfwd","g":"change","word":"Поправка со нова верзија","text":"Поправање лошо издание со брзо пуштање нова, поправена верзија наместо враќање на старата.","also":["rolling forward","rolled forward","поправка со нова верзија"]},{"id":"canary","g":"change","word":"Canary издание","text":"Пуштање промена прво за мала група, а за сите дури откако ќе изгледа во ред. Името доаѓа од канаринците што рударите ги носеле под земја како рано предупредување.","also":["canary releases","canary","canary изданија"]},{"id":"bluegreen","g":"change","word":"Сино-зелен деплој","text":"Чување две копии од активниот систем и префрлување на сите корисници на новата одеднаш, за лесно да се вратат назад ако нешто тргне наопаку.","also":["blue-green","blue green deployment","blue-green deployment","сино-зелен деплој"]},{"id":"zerodown","g":"change","word":"Деплој без прекин","text":"Пуштање нова верзија без услугата да запре за корисниците.","also":["zero downtime","zero-downtime","деплој без прекин"]},{"id":"chgenable","g":"change","word":"Овозможување промени","text":"Помагање промените да успеат: процена на ризикот, соодветно одобрение и избор на добар момент. Се нарекува и управување со промени.","also":["change management","управување со промени"]},{"id":"cab","g":"change","word":"Советодавен одбор за промени (CAB)","text":"Група што ги разгледува важните промени и се договара дали и кога може да се спроведат.","also":["CAB"]},{"id":"stdchange","g":"change","word":"Стандардна промена","text":"Нискоризична промена што секојпат се прави на ист испробан начин, па е однапред одобрена.","also":["standard changes","стандардни промени"]},{"id":"normchange","g":"change","word":"Редовна промена","text":"Промена што мора да се провери и одобри пред да се спроведе.","also":["normal changes","редовни промени"]},{"id":"emergchange","g":"change","word":"Итна промена","text":"Промена што мора веднаш да се направи за да се поправи или спречи сериозен проблем, со соодветно забрзано одобрување.","also":["emergency changes","итни промени"]},{"id":"automation","g":"change","word":"Автоматизација","text":"Препуштање повторлива работа на компјутерот за да се прави побрзо и на ист начин секојпат.","also":["automated","автоматизирано"],"noTip":1},{"id":"infra","g":"change","word":"Инфраструктура","text":"Уредите, мрежите и услугите на кои работи софтверот.","also":["infra"]},{"id":"iac","g":"change","word":"Инфраструктура како код (IaC)","text":"Опишување на серверите и поставките во датотеки што се чуваат со кодот, за секојпат да можат да се изградат на потполно ист начин.","also":["IaC"]},{"id":"cloud","g":"change","word":"Облак","text":"Изнајмување компјутери, простор за чување и услуги од голем давател преку интернет, наместо да поседуваш сопствени уреди.","also":["the cloud","cloud computing","облачно пресметување"]},{"id":"provider","g":"change","word":"Давател на облачни услуги","text":"Компанија што изнајмува компјутерски ресурси преку интернет, како Amazon Web Services (AWS), Microsoft Azure или Google Cloud.","also":["cloud providers","даватели на облачни услуги"]},{"id":"hosting","g":"change","word":"Хостинг","text":"Местото каде што живее и работи твојата апликација или веб-страница за луѓето да можат да ја посетат, обично изнајмено од компанија.","also":["веб-хостинг"]},{"id":"domain","g":"change","word":"Име на домен","text":"Веб-адресата што луѓето ја внесуваат, како example.com. Се изнајмува годишно, па мора да се обновува.","also":["domain names","domain","домен","имиња на домени"]},{"id":"dns","g":"change","word":"DNS","text":"Кратенка за систем на доменски имиња: интернет-именикот што име како example.com го претвора во адреса на вистинскиот компјутер.","also":["domain name system","систем на доменски имиња"]},{"id":"container","g":"change","word":"Контејнер","text":"Затворен пакет со апликацијата и сè што ѝ треба, за да работи исто на секој компјутер. Docker е најпознатата алатка.","also":["containers","Docker","контејнери"],"noTip":1},{"id":"vm","g":"change","word":"Виртуелна машина (VM)","text":"Симулиран компјутер што работи во вистински, за еден голем уред да може да се однесува како повеќе.","also":["VM","VMs","virtual machines","виртуелни машини"]},{"id":"serverless","g":"change","word":"Serverless","text":"Извршување код без да мораш да се грижиш за сервери: давателот го извршува кога треба, а плаќаш само за искористеното."},{"id":"lb","g":"change","word":"Распределувач на оптоварување","text":"Нешто што ги распределува посетителите на повеќе сервери, за ниту еден да не се преоптовари.","also":["load balancers","распределувачи на оптоварување"]},{"id":"cache","g":"change","word":"Кеш","text":"Блиска, лесно достапна збирка неодамнешни резултати, за истото да не мора повторно да се презема или пресметува. Чистењето може да поправи страници што изгледаат застарено.","also":["caches","caching","cached","кеширање"]},{"id":"cdn","g":"change","word":"Мрежа за испорака на содржина (CDN)","text":"Светска мрежа од сервери што чуваат копии од твоите страници и слики близу до посетителите, за брзо да се вчитуваат.","also":["CDN"]},{"id":"migration","g":"change","word":"Миграција","text":"Преместување податоци или системи од стара во нова поставеност, или внимателно менување на структурата на база на податоци.","also":["migrations","database migration","миграции","миграција на база"]},{"id":"service","g":"run","word":"Услуга","text":"Нешто што си го изградил и на што луѓето се потпираат, како веб-страница или апликација, за кое се грижи некој за да продолжи да работи. Штиклирај „Овој проект е услуга“ и кажи што нуди, кој ја користи и кој е на дежурство.","also":["услуги","услугата","услугите"]},{"id":"uptimepct","g":"run","word":"Време на достапност","text":"Колкав дел од времето услугата работи, обично изразен во проценти. И 99,9 % дозволува околу 43 минути прекин месечно.","also":["uptime percentage","процент на достапност"]},{"id":"uptime","g":"run","word":"Проверка на достапност","text":"Автоматска проверка, на секои неколку минути, дека твојата услуга сè уште одговара. Ако не успее неколку пати по ред, AI-gile сам отвора картичка за инцидент.","also":["uptime checks","проверки на достапност"]},{"id":"statuspage","g":"run","word":"Страница со статус","text":"Јавна страница што покажува дали услугата работи (зелено, портокалово или црвено) со најновата вест, за луѓето што ја користат да проверат наместо да прашуваат.","also":["страници со статус","страницата со статус"]},{"id":"desk","g":"run","word":"Биро за услуги","text":"Местото каде што пристигнуваат прашањата и пријавите од луѓето што ја користат твојата услуга. AI-gile ја распоредува секоја како барање, инцидент или идеја и кажува кога личи на нешто веќе пријавено.","also":["бироа за услуги","биро за помош","help desk"]},{"id":"svcrequest","g":"run","word":"Барање за услуга","text":"Некој бара нешто обично, на пример нова сметка или малку помош, наместо да пријави дека нешто е расипано. Чека на ред; инцидентот оди прв.","also":["барања за услуга"]},{"id":"incident","g":"run","word":"Инцидент","text":"Нешто што во моментот е расипано или не работи правилно за корисниците, како недостапна или многу бавна веб-страница. 🔥 Картичката за инцидент оди пред другите: прво се враќа услугата во функција.","also":["инциденти","инцидентот","инцидентите"]},{"id":"major","g":"run","word":"Голем инцидент","text":"Голем инцидент: погодени многу луѓе, или пари или податоци во опасност. Едно копче ги става сите тимови на него (рој), го буди тој што е на дежурство и бара ажурирање на статусот на секои 30 минути.","also":["големи инциденти","големиот инцидент"]},{"id":"oncall","g":"run","word":"Дежурство","text":"Да бидеш тој што одговара кога нешто ќе се расипе, дури и ноќе. Секоја услуга има член на тимот на дежурство кој прв се буди за нејзините инциденти.","also":["на дежурство","дежурниот","дежурен","on-call"]},{"id":"replyby","g":"run","word":"Рок за одговор","text":"Колку долго картичка смее да чека на прв одговор, на пример еден час за инцидент. После тоа добива црвен часовник, за ништо да не се заборави тивко. Се вика и цел за одговор.","also":["рокови за одговор","рокот за одговор","цел за одговор","цели за одговор"]},{"id":"postmortem","g":"run","word":"Анализа по инцидент","text":"Краток поглед наназад по инцидент: што се случи, што помогна и што да се смени, без да се обвинува никој. Инцидент не може да се затвори без неа.","also":["анализи по инцидент","анализата по инцидент","post-mortem","postmortem"]},{"id":"problem","g":"run","word":"Проблем","text":"Скриената причина зад еден или повеќе инциденти. 🧩 Картичка за проблем ги групира инцидентите што постојано се враќаат, за причината да се најде и поправи засекогаш.","also":["проблеми","проблемот","проблемите"],"noTip":1},{"id":"rootcause","g":"run","word":"Основна причина","text":"Вистинската причина зошто нешто се расипало, а не само она што си го видел дека тргнало наопаку. Поправи ја основната причина и инцидентот престанува да се враќа.","also":["основни причини","основната причина"]},{"id":"workaround","g":"run","word":"Заобиколно решение","text":"Начин работите да продолжат да функционираат додека вистинската поправка не е готова, на пример рестартирање на нешто кога ќе заглави. Се запишува на картичката за проблем за никој да не мора пак да го смислува.","also":["заобиколни решенија","заобиколното решение","привремено решение"]},{"id":"knownerror","g":"run","word":"Позната грешка","text":"Проблем чија причина е позната, но сè уште не е поправен, обично со запишано заобиколно решение. 🧩 Познати грешки ги наведува, за сите да го користат заобиколното решение наместо повторно да истражуваат.","also":["познати грешки","познатата грешка","познатите грешки"]},{"id":"runbook","g":"run","word":"Runbook","text":"Упатство чекор по чекор за поправање на позната врста проблем, за да се прави на ист начин, брзо, секој пат. По голем инцидент тимот може да предложи еден, а ти да дадеш ОК.","also":["runbook-ови","runbook-от"]},{"id":"ci","g":"run","word":"Ставка на конфигурација","text":"Една работа од која зависи твојата услуга, на пример сервер, домен, сертификат, клуч или добавувач. 🗂️ Ставки на конфигурација ги наведува по услуга, за да видиш што погодува еден инцидент и што треба да се обнови или да има резервна копија.","also":["ставки на конфигурација"]},{"id":"expiry","g":"run","word":"Датум на истекување","text":"Датумот кога нешто престанува да работи ако не се обнови, како безбедносен сертификат или веб-адреса. AI-gile ги следи датумите и создава по една картичка за обновување 30 дена порано, за ништо ненадејно да не запре.","also":["датуми на истекување","истекување","следење на истекување"]},{"id":"backup","g":"run","word":"Резервна копија","text":"Зачувана копија од твоите податоци од порано, на која можеш да се потпреш ако нешто се изгуби или оштети. AI-gile секој ден прави резервна копија од твоите табли.","also":["резервни копии","резервната копија","резервните копии","бекап"]},{"id":"restore","g":"run","word":"Обновување","text":"Враќање на податоци од резервна копија. Резервната копија навистина важи дури кога знаеш дека може да се обнови, па вреди да се проба одвреме-навреме.","also":["обнови","обновено","обновени","обновувањето"]},{"id":"svcreview","g":"run","word":"Преглед на услугата","text":"Поглед наназад на еден месец од една услуга: отворени и поправени инциденти, колку брзо луѓето добиле одговор, достапност и потрошени токени. Месечниот преглед го покажува тоа за секоја услуга.","also":["прегледи на услуги","месечен преглед","месечни прегледи"]},{"id":"accessreview","g":"run","word":"Преглед на пристап","text":"Проверка на секои 90 дена кој сè уште има пристап: споделени врски, улоги на пријателите и зачувани лозинки и клучеви. За секоја ставка одлучуваш дали да остане или да се отстрани, за стариот пристап да не се задржува.","also":["прегледи на пристап"]},{"id":"improvements","g":"run","word":"Листа на подобрувања","text":"Сè што тимот одлучил да подобри, на едно место: предлози од ретро, акции од прегледи и поправки на проблеми, секое со својот статус. Ќе ја најдеш под 📈 Подобрувања.","also":["листи на подобрувања","подобрувања"]},{"id":"tokencap","g":"run","word":"Граница на токени","text":"Месечна граница на токените што агентите на една услуга смеат да ги потрошат. На 80% добиваш предупредување; на 100% нивната работа во позадина чека до следниот месец или додека не ја зголемиш границата.","also":["граници на токени"]},{"id":"svcmgmt","g":"run","word":"Управување со услуги","text":"Сè што е потребно услугата секојдневно да остане корисна и функционална за луѓето што се потпираат на неа.","also":["управување со услуга"]},{"id":"itil","g":"run","word":"ITIL","text":"Широко користен водич за добро управување со услуги, со теми како инциденти, проблеми и промени. Името некогаш значело библиотека за ИТ-инфраструктура."},{"id":"itsm","g":"run","word":"Управување со ИТ-услуги (ITSM)","text":"Обезбедување технологија како услуга за луѓето, со јасни начини за обработка на барања, инциденти, промени и подобрувања.","also":["ITSM"]},{"id":"managed","g":"run","word":"Управувана услуга","text":"Услуга што некој друг ја води и одржува за тебе, според договор за тоа колку добро мора да работи.","also":["managed services","управувани услуги"]},{"id":"svcowner","g":"run","word":"Сопственик на услугата","text":"Човекот што одговара за услугата во целина: колку добро работи, колку чини и како се подобрува.","also":["service owners","сопственици на услуги"]},{"id":"sla","g":"run","word":"Договор за ниво на услуга (SLA)","text":"Писмено ветување до клиентите за квалитетот на услугата, како „достапна 99,9 % од времето“ или „одговор во еден час“, често со враќање пари ако не се исполни.","also":["SLA","SLAs","service level agreement","договор за ниво на услуга"]},{"id":"slo","g":"run","word":"Цел за ниво на услуга (SLO)","text":"Сопствената цел на тимот за тоа колку добро треба да работи услугата во одреден период, обично малку построга од SLA за поголема сигурност.","also":["SLO","SLOs"]},{"id":"sli","g":"run","word":"Показател за ниво на услуга (SLI)","text":"Вистинското мерење што го споредуваш со целта, како уделот на посети што се вчитале успешно.","also":["SLI","SLIs"]},{"id":"availability","g":"run","word":"Достапност","text":"Дали луѓето можат да ја користат услугата кога им треба, често мерено како време на достапност.","also":["high availability","висока достапност"]},{"id":"downtime","g":"run","word":"Прекин на работа","text":"Времето кога услугата не работи или е исклучена, планирано или не.","also":["down time","време на прекин"]},{"id":"errorbudget","g":"run","word":"Дозволен буџет за грешки","text":"Малата количина неуспех што ја дозволува твојата цел за доверливост. Додека има остаток можеш да ризикуваш со промени; кога ќе се потроши, забавуваш.","also":["error budgets","буџети за грешки"]},{"id":"outage","g":"run","word":"Испад","text":"Период кога услугата е недостапна или сериозно нарушена за корисниците.","also":["outages","испади"]},{"id":"degraded","g":"run","word":"Нарушена работа","text":"Работи, но лошо: бавно или со делови што не функционираат.","also":["degraded service","нарушена услуга"]},{"id":"monitoring","g":"run","word":"Следење","text":"Постојано автоматско следење на услугата за проблемите да се забележат, по можност пред корисниците.","also":["надгледување"]},{"id":"observability","g":"run","word":"Набљудливост","text":"Колку добро можеш однадвор да разбереш што се случува во системот, преку неговите дневници, бројки и траги.","also":["o11y"]},{"id":"log","g":"run","word":"Дневник","text":"Дневник што програмата постојано го води за својата работа, за да се открие што тргнало наопаку.","also":["logs","logging","дневници","евидентирање"],"noTip":1},{"id":"trace","g":"run","word":"Трага на барање","text":"Запис за патувањето на едно барање низ деловите на системот, чекор по чекор, што покажува каде забавило.","also":["traces","tracing","следење на барања"]},{"id":"latency","g":"run","word":"Латенција","text":"Колку време е потребно за одговор, како чекањето меѓу кликнувањето и појавувањето на страницата.","also":["латенции"]},{"id":"alert","g":"run","word":"Предупредување","text":"Автоматска порака дека на нешто му треба внимание, како веб-страница што не одговара.","also":["alerts","alerting","предупредувања"],"noTip":1},{"id":"alertfatigue","g":"run","word":"Замор од предупредувања","text":"Кога има толку многу предупредувања што луѓето почнуваат да ги игнорираат, вклучувајќи ги важните.","also":["alarm fatigue","замор од аларми"]},{"id":"dashboard","g":"run","word":"Контролна табла","text":"Екран што со еден поглед ги прикажува најважните бројки и состојби.","also":["dashboards","контролни табли"],"noTip":1},{"id":"paging","g":"run","word":"Итно повикување","text":"Итно повикување или будење на дежурното лице поради проблем.","also":["paged","итно повикан"]},{"id":"escalation","g":"run","word":"Ескалација","text":"Вклучување некого со повеќе знаење или овластување кога проблемот не може да се реши на тековното ниво или не доволно брзо.","also":["escalate","escalated","ескалира","ескалирано"]},{"id":"triage","g":"run","word":"Тријажа","text":"Брзо подредување на пристигнатите проблеми според итност и важност, за најтешките да се решаваат први.","also":["triaged","тријажирано"]},{"id":"impact","g":"run","word":"Влијание","text":"Колку нешто ги засега луѓето: колкумина и колку сериозно.","noTip":1},{"id":"urgency","g":"run","word":"Итност","text":"Колку брзо мора да се постапи. Влијанието и итноста заедно го одредуваат приоритетот.","noTip":1},{"id":"plevels","g":"run","word":"Нивоа на приоритет (P1, P2…)","text":"Ознаки за итноста на проблемот. P1 е најсериозен и бара веднаш да се реагира.","also":["P1","P2","P3","P4"]},{"id":"queue","g":"run","word":"Ред на барања","text":"Листа на барања и инциденти што чекаат некој да ги преземе.","also":["ticket queues","редови на барања"]},{"id":"tiers","g":"run","word":"Прва и втора линија на поддршка","text":"Нивоа на поддршка: првата линија го прима повикот и решава едноставни работи, а втората има подлабоко знаење за потешките. Се нарекуваат и ниво 1 и ниво 2.","also":["first-line support","tier 1","tier 2","прва линија","втора линија"]},{"id":"ic","g":"run","word":"Раководител на инцидентот","text":"Едното лице што го води одговорот на инцидентот, за сите да знаат кој одлучува и кој што прави.","also":["incident commanders","раководители на инциденти"]},{"id":"responsetime","g":"run","word":"Време на одговор","text":"Колку време минува пред некој првпат да преземе барање или инцидент.","also":["response times","времиња на одговор"]},{"id":"resolution","g":"run","word":"Време за решавање","text":"Колку време е потребно целосно да се реши барање или инцидент, од пријавата до поправката.","also":["resolution times","time to resolve","време до решение"]},{"id":"mttr","g":"run","word":"Просечно време за опоравување (MTTR)","text":"Колку време во просек е потребно услугата повторно да проработи по дефект. MTTR може да значи малку различни работи, па кажи што мериш.","also":["MTTR","mean time to restore","просечно време за обновување"]},{"id":"mtbf","g":"run","word":"Просечно време меѓу дефекти (MTBF)","text":"Колку време во просек работи услугата пред нешто да се расипе.","also":["MTBF"]},{"id":"cmdb","g":"run","word":"База за управување со конфигурации (CMDB)","text":"Листата на сите конфигурациски ставки и нивните врски, за да видиш што од што зависи.","also":["CMDB"]},{"id":"asset","g":"run","word":"Средство","text":"Нешто вредно што го поседуваш или го плаќаш за услугата, како лаптоп, софтверска лиценца или домен.","also":["assets"],"noTip":1},{"id":"capplan","g":"run","word":"Планирање капацитет","text":"Обезбедување доволно компјутерска моќ, простор за податоци и луѓе за претстојните потреби.","also":["capacity plan","план за капацитет"]},{"id":"scaling","g":"run","word":"Зголемување на капацитетот","text":"Справување со повеќе корисници со зголемување на моќноста на еден уред или со додавање повеќе уреди.","also":["scale up","scale out","scaling up","scaling out","вертикално скалирање","хоризонтално скалирање"]},{"id":"bcp","g":"run","word":"Континуитет на деловното работење","text":"Планови за продолжување на важната работа кога ќе се случи голем проблем, како губење канцеларија, клучен добавувач или компјутери.","also":["business continuity plan","план за деловен континуитет"]},{"id":"dr","g":"run","word":"Опоравување по катастрофа (DR)","text":"Планот и алатките за враќање на услугата по сериозен настан, како губење цел податочен центар.","also":["disaster recovery","опоравување по катастрофа"]},{"id":"rto","g":"run","word":"Целно време за опоравување (RTO)","text":"Најдолгото дозволено време на прекин по катастрофа пред услугата да мора повторно да работи.","also":["RTO"]},{"id":"rpo","g":"run","word":"Целна точка за опоравување (RPO)","text":"Колку неодамнешни податоци можеш да си дозволиш да изгубиш, мерено во време. RPO од еден час значи резервни копии најмалку секој час.","also":["RPO"]},{"id":"redundancy","g":"run","word":"Резервираност","text":"Имање подготвени резерви, како втор сервер, за еден дефект да не ја запре услугата."},{"id":"failover","g":"run","word":"Автоматско префрлување на резерва","text":"Самостојно префрлување на резервен систем кога вообичаениот ќе откаже.","also":["fail over","префрлување на резерва"]},{"id":"spof","g":"run","word":"Единечна точка на отказ","text":"Еден дел што го урива целиот систем кога ќе се расипе, бидејќи нема резерва.","also":["single points of failure","SPOF","единечни точки на отказ"]},{"id":"maintwin","g":"run","word":"Термин за одржување","text":"Планирано време кога услугата може да запре или да забави поради одржување, најавено однапред на корисниците.","also":["maintenance windows","planned maintenance","планирано одржување"]},{"id":"handover","g":"run","word":"Предавање","text":"Пренесување работа, знаење и одговорност на друг човек или тим, за ништо да не се изгуби.","also":["handovers"]},{"id":"kb","g":"run","word":"База на знаење","text":"Збирка статии за помош и одговори, за корисниците и за тимот.","also":["knowledge bases","бази на знаење"]},{"id":"csat","g":"run","word":"Задоволство на клиентите (CSAT)","text":"Оценка од корисниците за тоа колку биле задоволни, често побарана по затворање на барањето.","also":["CSAT"]},{"id":"supplier","g":"run","word":"Добавувач","text":"Надворешна компанија на која се потпираш, како давателот на хостинг. Се нарекува и vendor или трета страна.","also":["suppliers","vendor","vendors","third party","добавувачи","трета страна"],"noTip":1},{"id":"retire","g":"run","word":"Повлекување на услуга","text":"Безбедно трајно исклучување услуга: известување на корисниците, средување на податоците и пристапот и запирање на трошоците.","also":["retiring a service","укинување услуга"]},{"id":"eol","g":"run","word":"Крај на поддршката (EOL)","text":"Кога производот престанува да добива ажурирања или поддршка од производителот, па треба да се замени.","also":["EOL","end-of-life","крај на животниот век"]},{"id":"cybersec","g":"sec","word":"Сајбербезбедност","text":"Заштита на системите и податоците од упад, кражба или оштетување.","also":["cyber security","сајбер безбедност"]},{"id":"authn","g":"sec","word":"Автентикација","text":"Проверка кој е некој, обично со лозинка или код. Често се скратува како authn.","also":["authn","проверка на идентитетот"]},{"id":"authz","g":"sec","word":"Авторизација","text":"Проверка што смее да прави некој откако знаеш кој е. Често се скратува како authz.","also":["authz","authorization","проверка на овластувањата"]},{"id":"mfa","g":"sec","word":"Повеќефакторска автентикација (MFA)","text":"Најавување со два или повеќе докази, како лозинка и код на телефонот. Кога има два, се нарекува и двофакторска автентикација или 2FA.","also":["MFA","2FA","two-factor","two-factor authentication","двофакторска автентикација"]},{"id":"sso","g":"sec","word":"Единствено најавување (SSO)","text":"Едно најавување за пристап до повеќе системи, како користење на работната сметка насекаде.","also":["SSO"]},{"id":"pwmgr","g":"sec","word":"Управувач со лозинки","text":"Апликација што создава силни лозинки и ги памети за тебе.","also":["password managers","управувачи со лозинки"]},{"id":"secret","g":"sec","word":"Тајна","text":"Лозинка, клуч или друг приватен код што програма го користи за пристап. Никогаш не смее да се споделува или да се запишува во кодот.","also":["secrets","тајни"],"noTip":1},{"id":"apikey","g":"sec","word":"API-клуч","text":"Таен код што ѝ дозволува на програма да користи API на друга услуга и покажува кој го користи и плаќа за него.","also":["API keys","API-клучеви"]},{"id":"accesstoken","g":"sec","word":"Токен за пристап","text":"Привремена пропусница што докажува дека програмата има дозвола за пристап, за да не ја бара твојата лозинка секојпат. Не е исто што и AI токен.","also":["access tokens","токени за пристап"]},{"id":"encryption","g":"sec","word":"Шифрирање","text":"Претворање на информациите во нечитлив облик што може да го прочита само некој со вистинскиот клуч.","also":["encrypted","encrypt","шифрирано"]},{"id":"https","g":"sec","word":"HTTPS","text":"Безбедниот начин на пренос на веб-страници, означен со катанец во прелистувачот, за никој по пат да не може да ги чита или менува."},{"id":"cert","g":"sec","word":"SSL/TLS сертификат","text":"Дигитална лична карта со која веб-страницата го докажува идентитетот и користи HTTPS. Има рок, па мора да се обновува.","also":["TLS certificate","SSL certificate","certificate","certificates","сертификат","сертификати"]},{"id":"permissions","g":"sec","word":"Дозволи","text":"Правилата за тоа кој што смее да гледа или менува.","also":["permission"],"noTip":1},{"id":"leastpriv","g":"sec","word":"Најмали потребни привилегии","text":"Давање само на пристапот што навистина му треба на секој човек или програма, само онолку долго колку што е потребно.","also":["principle of least privilege","принцип на најмали привилегии"]},{"id":"rbac","g":"sec","word":"Контрола на пристап според улога (RBAC)","text":"Давање пристап според улогата, како прегледувач или уредувач, наместо поединечно за секој човек.","also":["RBAC","role-based access","пристап според улога"]},{"id":"vuln","g":"sec","word":"Ранливост","text":"Слабост што некој би можел да ја искористи за упад или нанесување штета.","also":["vulnerabilities","ранливости"]},{"id":"zeroday","g":"sec","word":"Нулти ден","text":"Слабост за која напаѓачите знаат пред создавачите да имаат време да ја поправат.","also":["zero-days","zero day","ранливост од нулти ден"]},{"id":"malware","g":"sec","word":"Злонамерен софтвер","text":"Штетен софтвер, како вируси, создаден за оштетување, шпионирање или кражба."},{"id":"ransomware","g":"sec","word":"Софтвер за изнуда","text":"Злонамерен софтвер што ги заклучува датотеките и бара пари за да ги отклучи. Добрите резервни копии се најдобрата одбрана.","also":["ransomware attack","напад со изнуда"]},{"id":"phishing","g":"sec","word":"Фишинг","text":"Лажни пораки што се обидуваат да те измамат да дадеш лозинки или пари, или да отвориш нешто штетно.","also":["phishing email","phishing emails","измамнички пораки"]},{"id":"socialeng","g":"sec","word":"Социјален инженеринг","text":"Измамување луѓе наместо компјутери за да се добие пристап, како лажен повик од „ИТ-поддршка“."},{"id":"firewall","g":"sec","word":"Заштитен ѕид","text":"Чувар што одлучува кој мрежен сообраќај смее да влезе или излезе.","also":["firewalls","заштитни ѕидови"]},{"id":"vpn","g":"sec","word":"VPN","text":"Кратенка за виртуелна приватна мрежа: приватна, шифрирана врска преку интернет, често за безбеден пристап до работни системи.","also":["virtual private network","виртуелна приватна мрежа"]},{"id":"ddos","g":"sec","word":"Оневозможување услуга (DoS, DDoS)","text":"Преплавување услуга со толку многу лажен сообраќај што вистинските луѓе не можат да ја користат. DDoS значи дека доаѓа од многу компјутери истовремено.","also":["DoS","DDoS","denial of service","DDoS attack","DDoS-напад"]},{"id":"pentest","g":"sec","word":"Пенетрациски тест (pen test)","text":"Ангажирање доверливи стручњаци да се обидат да пробијат систем, за слабостите да се најдат пред вистинските напаѓачи.","also":["pen test","pen testing","penetration testing","pentest","пенетрациско тестирање"]},{"id":"audit","g":"sec","word":"Безбедносна ревизија","text":"Внимателна проверка колку добро е нешто заштитено, според список на добри практики.","also":["security audits","безбедносни ревизии"]},{"id":"threatmodel","g":"sec","word":"Моделирање закани","text":"Размислување кој би можел да нападне нешто, на кој начин и што може да се направи за тоа да се спречи.","also":["threat model","threat modeling","модел на закани"]},{"id":"breach","g":"sec","word":"Протекување на податоци","text":"Кога приватни информации стигнуваат до луѓе што не смеат да ги имаат, или се губат или менуваат без дозвола.","also":["data breaches","data breach","протекување податоци"]},{"id":"pii","g":"sec","word":"Лични податоци","text":"Секоја информација за човек што може да се идентификува, како име, адреса на е-пошта или локација. Се нарекува и PII.","also":["PII","personally identifiable information","информации за лична идентификација"]},{"id":"gdpr","g":"sec","word":"GDPR","text":"Европскиот закон за лични податоци (Обединетото Кралство има своја верзија): собирај само што ти треба, чувај го безбедно и дозволи им на луѓето да ги видат или избришат своите податоци.","also":["General Data Protection Regulation","Општа регулатива за заштита на податоците"]},{"id":"dataprot","g":"sec","word":"Заштита на податоците","text":"Правилна грижа за личните податоци во согласност со законот.","also":["data protection law","закон за заштита на податоците"]},{"id":"privacypolicy","g":"sec","word":"Политика за приватност","text":"Јавна страница што кажува кои лични податоци ги собираш, зошто и што правиш со нив.","also":["privacy statement","privacy notice","известување за приватност"]},{"id":"consent","g":"sec","word":"Согласност","text":"Јасно и слободно „да“ од човек за користење на неговите податоци на одреден начин. Може да го повлече во секое време.","also":["opt-in","изречна согласност"],"noTip":1},{"id":"cookie","g":"sec","word":"Колаче","text":"Мала датотека што веб-страницата ја зачувува во прелистувачот за да запомни нешта, како најавувањето. За некои прво е потребна твоја согласност.","also":["cookies","колачиња"],"noTip":1},{"id":"minimisation","g":"sec","word":"Минимизирање на податоците","text":"Собирање и чување само на личните податоци што навистина ти се потребни за работата.","also":["data minimization","намалување на податоците"]},{"id":"retention","g":"sec","word":"Чување на податоците","text":"Колку долго се чуваат податоците пред бришење. Побезбедно е да не се чуваат подолго од потребното, а често тоа го бара и законот.","also":["retention period","рок на чување"]},{"id":"anon","g":"sec","word":"Анонимизација","text":"Менување на податоците така што повеќе никој не може разумно да се идентификува преку нив.","also":["anonymised","anonymization","anonymous data","анонимни податоци"]},{"id":"pseudo","g":"sec","word":"Псевдонимизација","text":"Заменување имиња и други детали со шифри, со одделно чуван клуч за повторно поврзување. Тоа сè уште се лични податоци.","also":["pseudonymised","pseudonymization","псевдонимизирани податоци"]},{"id":"dpa","g":"sec","word":"Договор за обработка на податоци (DPA)","text":"Договор што кажува како добавувачот смее да обработува лични податоци во твое име.","also":["DPA"]},{"id":"dpia","g":"sec","word":"Процена на влијанието врз заштитата на податоците (DPIA)","text":"Внимателна проверка пред почетокот како планираното користење лични податоци може да влијае врз луѓето и како да се намалат ризиците.","also":["DPIA"]},{"id":"auditlog","g":"sec","word":"Ревизорски дневник","text":"Запис кој што направил и кога, за постапките подоцна да можат да се проверат.","also":["audit logs","audit trail","ревизорска трага"]},{"id":"compliance","g":"sec","word":"Усогласеност","text":"Почитување на законите, правилата и стандардите што важат за тебе и можност тоа да се покаже.","also":["compliant","усогласено"]},{"id":"iso","g":"sec","word":"ISO 27001","text":"Познат меѓународен стандард за управување со безбедноста на информациите. Компаниите можат да добијат сертификат според него.","also":["ISO/IEC 27001"]},{"id":"soc","g":"sec","word":"SOC 2","text":"Американски извештај, проверен од надворешни ревизори, што покажува дека компанијата правилно се грижи за податоците на клиентите.","also":["SOC2"]},{"id":"agent","g":"ai","word":"Агент","text":"AI што самостојно работи на задача: го чита кодот, прави промени, извршува проверки и известува. Неговата работа сепак се проверува.","also":["агенти","agents"]},{"id":"token","g":"ai","word":"Токен","text":"Малите парчиња текст што AI ги чита и пишува, секое приближно три четвртини од збор. Користењето на AI се брои во токени, па со помалку токени ти останува повеќе од планот.","also":["токени","tokens"]},{"id":"hook","g":"ai","word":"Hook","text":"Мала наредба што сама се извршува во одреден момент, на пример кога почнува AI сесија, за тимот да ги слушне твоите коментари.","also":["hooks","хукови"]},{"id":"ai","g":"ai","word":"Вештачка интелигенција (AI)","text":"Компјутерски системи што прават нешта за кои обично мислиме дека е потребен човек, како пишување, одговарање прашања или препознавање слики.","also":["AI","artificial intelligence","вештачка интелигенција","ВИ"],"noTip":1},{"id":"ml","g":"ai","word":"Машинско учење (ML)","text":"Начин компјутерите да учат обрасци од многу примери, наместо да добиваат точни правила.","also":["machine learning","машинско учење"]},{"id":"model","g":"ai","word":"Модел","text":"Обучениот „мозок“ на AI систем, создаден со учење од огромен број примери. Моделите се разликуваат по вештини, брзина и цена.","also":["models","AI model","модели","AI модел"],"noTip":1},{"id":"llm","g":"ai","word":"Голем јазичен модел (LLM)","text":"AI модел обучен на огромно количество текст, за да може да чита и пишува јазик.","also":["LLM","LLMs"]},{"id":"genai","g":"ai","word":"Генеративен AI","text":"AI што создава нови нешта, како текст, слики или код, наместо само да ги подредува или препознава.","also":["GenAI","генеративна вештачка интелигенција"]},{"id":"chatbot","g":"ai","word":"Четбот","text":"Програма со која разговараш на секојдневен јазик, со пишување или зборување.","also":["chatbots","четботови"]},{"id":"prompt","g":"ai","word":"Промпт","text":"Она што му го даваш на AI: прашање или насоки, заедно со сè што ќе му приложиш. Појасните промптови обично носат подобри одговори.","also":["prompts","промптови"]},{"id":"prompteng","g":"ai","word":"Промпт инженеринг","text":"Вештина на пишување промптови што даваат доверливи и корисни резултати.","also":["пишување промптови"]},{"id":"sysprompt","g":"ai","word":"Системски промпт","text":"Позадински насоки што AI ги добива пред почетокот на разговорот, со кои се поставуваат неговата улога и правила. Имаат поголема тежина од она што го пишуваш ти.","also":["system prompts","system instruction","system instructions","системски промптови"]},{"id":"context","g":"ai","word":"Контекст","text":"Сè што AI може да види додека работи: упатствата, твоите пораки, прочитаните датотеки и претходните одговори.","noTip":1},{"id":"ctxwin","g":"ai","word":"Контекстен прозорец","text":"Колку AI може да држи на ум одеднаш, мерено во токени. Над тоа, постарите делови се отфрлаат или сумираат.","also":["context windows","контекстни прозорци"]},{"id":"session","g":"ai","word":"Сесија","text":"Еден работен разговор со AI, од почеток до крај. Нова сесија почнува со свежа меморија.","also":["sessions","сесии"],"noTip":1},{"id":"memory","g":"ai","word":"Меморија","text":"Белешки што AI ги чува меѓу сесиите, за да ги памети твоите претпочитања и претходните одлуки.","noTip":1},{"id":"hallucination","g":"ai","word":"Халуцинација","text":"Кога AI кажува нешто самоуверено, а тоа е измислено или погрешно. Проверувај ги важните факти.","also":["hallucinations","hallucinate","hallucinates","халуцинации"]},{"id":"training","g":"ai","word":"Обучување","text":"Подучување модел со огромен број примери пред некој да почне да го користи.","also":["trained","обучен"],"noTip":1},{"id":"trainingdata","g":"ai","word":"Податоци за обучување","text":"Примерите од кои учел моделот. Неговото знаење запира на датумот кога биле собрани тие податоци.","also":["training set","збирка за обучување"]},{"id":"cutoff","g":"ai","word":"Граница на знаењето","text":"Датумот до кој стигнува вграденото знаење на AI. Нема да знае за подоцнежни работи освен ако не ги пребара.","also":["training cutoff","краен датум на обучување"]},{"id":"finetune","g":"ai","word":"Дополнително обучување","text":"Дополнително обучување постоен модел со твои примери за подобро да извршува одредена работа.","also":["fine-tune","fine-tuned","fine tuning","фино дотерување"]},{"id":"inference","g":"ai","word":"Инференција","text":"Вистинско користење на AI модел за да одговори на нешто, за разлика од неговото обучување.","also":["model inference","извршување на моделот"]},{"id":"tooluse","g":"ai","word":"Користење алатки","text":"Можноста AI да прави нешта, а не само да зборува: да извршува наредби, да чита датотеки или да пребарува на интернет, преку алатки што му ги дава апликацијата.","also":["tool calling","tool call","tool calls","повикување алатки"]},{"id":"subagent","g":"ai","word":"Подагент","text":"Помошен AI на кој главниот AI му предава помала задача и од кој го добива резултатот назад.","also":["subagents","sub-agent","подагенти"]},{"id":"multiagent","g":"ai","word":"Повеќеагентска работа","text":"Неколку AI агенти што работат заедно на една задача, секој со свој дел, како мал тим.","also":["multi-agent system","повеќеагентски систем"]},{"id":"autonomy","g":"ai","word":"Самостојност","text":"Колку AI смее да направи сам пред да мора да праша човек.","also":["autonomous","автономија"]},{"id":"hitl","g":"ai","word":"Човек вклучен во процесот","text":"Човек останува вклучен за да проверува или одобрува што прави AI во клучни моменти. Во AI-gile тоа си ти.","also":["human-in-the-loop","HITL"]},{"id":"guardrails","g":"ai","word":"Заштитни ограничувања","text":"Ограничувања и проверки што го држат дејствувањето на AI безбедно, како барање одобрение пред нешто да оди во живо. Го намалуваат ризикот од грешки, но не го отстрануваат целосно.","also":["guardrail","заштитна мерка"]},{"id":"rag","g":"ai","word":"Генерирање поткрепено со пребарување (RAG)","text":"Дозволување AI да пребарува во твоите документи пред да одговори, за одговорите да се потпираат на твоите факти.","also":["RAG","retrieval augmented generation","генерирање со пребарување"]},{"id":"embedding","g":"ai","word":"Векторско претставување","text":"Претворање текст во список броеви што го опфаќа неговото значење, за компјутерот да најде нешта со слична смисла.","also":["embeddings","векторски претставувања"]},{"id":"vectordb","g":"ai","word":"Векторска база на податоци","text":"База направена за пребарување во тие списоци броеви и наоѓање материјал со слично значење.","also":["vector databases","vector store","векторско складиште"]},{"id":"mcp","g":"ai","word":"Протокол за контекст на моделот (MCP)","text":"Заеднички начин за поврзување алатки и извори на податоци со AI апликации, за AI да може да ги користи.","also":["MCP"]},{"id":"temperature","g":"ai","word":"Температура","text":"Поставка за тоа колку смели се одговорите на AI. Ниска вредност дава постабилни и попредвидливи одговори, а висока поразновидни. Ниедна не гарантира точност.","also":["model temperature","температура на моделот"],"noTip":1},{"id":"multimodal","g":"ai","word":"Мултимодален","text":"Способен да работи со повеќе видови информации, како текст, слики и звук.","also":["multi-modal","мултимодално"]},{"id":"evals","g":"ai","word":"Евалуација (eval)","text":"Планиран тест колку добро работи AI на избрани примери, за да споредиш модели или промптови.","also":["eval","evals","евалуации"]},{"id":"bias","g":"ai","word":"Пристрасност","text":"Кога AI (или човек) неправедно се наклонува на една страна, често поради она од што учел.","also":["biased","пристрасен"],"noTip":1},{"id":"responsible","g":"ai","word":"Одговорен AI","text":"Праведно, безбедно и чесно користење на AI, при што луѓето остануваат одговорни за резултатите.","also":["ethical AI","етички AI","одговорна вештачка интелигенција"]},{"id":"injection","g":"ai","word":"Prompt injection (вметнување промпт)","text":"Измама во која скриени упатства во веб-страница или датотека се обидуваат да го натераат AI да направи нешто што неговиот корисник не го побарал.","also":["prompt injections","prompt injection","вметнување промпт"]},{"id":"ratelimit","g":"ai","word":"Ограничување на бројот барања","text":"Граница за бројот на барања што смееш да ги испратиш до услуга во одредено време. Ако ја надминеш, мора да почекаш.","also":["rate limits","rate limited","rate limit"]},{"id":"usagelimit","g":"ai","word":"Ограничување на користењето","text":"Колку AI работа дозволува твојот план во одреден период; потоа таа се паузира или чини повеќе.","also":["usage limits","ограничувања на користењето"]},{"id":"vibe","g":"ai","word":"Vibe coding","text":"Создавање софтвер главно така што му опишуваш на AI што сакаш и го оставаш тој да го напише кодот.","also":["vibe-coding","програмирање преку опишување"]},{"id":"budget","g":"money","word":"Буџет","text":"Износот пари издвоен за нешто.","also":["budgets","буџети"],"noTip":1},{"id":"costest","g":"money","word":"Процена на трошоците","text":"Најдобрата претпоставка колку ќе чини нешто пред да почнеш.","also":["cost estimates","процени на трошоци"]},{"id":"roi","g":"money","word":"Поврат на инвестицијата (ROI)","text":"Она што го добиваш во споредба со вложеното. Ако е позитивен, вложувањето се исплатело.","also":["ROI"]},{"id":"tco","g":"money","word":"Вкупен трошок на сопственост (TCO)","text":"Сè што нешто навистина чини во целиот животен век, не само купувањето: работа, поддршка, надградби и конечно повлекување.","also":["TCO"]},{"id":"capex","g":"money","word":"CapEx и OpEx","text":"CapEx се пари потрошени однапред за нешта што ги задржуваш; OpEx се тековни трошоци, како месечни сметки.","also":["CapEx","OpEx","capital expenditure","operating expenditure","капитални расходи","оперативни расходи"]},{"id":"subscription","g":"money","word":"Претплата","text":"Редовно плаќање, обично месечно или годишно, за да продолжиш да користиш нешто.","also":["subscriptions","претплати"],"noTip":1},{"id":"saas","g":"money","word":"Софтвер како услуга (SaaS)","text":"Софтвер што го користиш на интернет и го плаќаш со претплата, додека создавачот го одржува за тебе.","also":["SaaS"]},{"id":"payg","g":"money","word":"Плаќање според користењето","text":"Плаќање само за искористеното, како облачни ресурси или AI токени.","also":["pay-as-you-go","usage-based pricing","наплата според користење"]},{"id":"overage","g":"money","word":"Надминување на пакетот","text":"Користење над она што го вклучува планот, што може дополнително да се наплати.","also":["overages","overage charges","доплата за надминување"]},{"id":"billingalert","g":"money","word":"Предупредување за трошоци","text":"Порака кога трошоците или користењето ќе го достигнат избраното ниво. Предупредува, но не секогаш ја запира понатамошната наплата.","also":["billing alerts","spending alert","предупредувања за трошоци"]},{"id":"freetier","g":"money","word":"Бесплатен пакет","text":"Бесплатно ниво на платена услуга, со ограничувања. Корисно за почеток.","also":["free plan","бесплатен план"]},{"id":"pricing","g":"money","word":"Ценовен план","text":"Различните пакети што ги продава услугата, секој со своја цена и ограничувања.","also":["pricing plans","price plan","ценовни планови"]},{"id":"licence","g":"money","word":"Лиценца","text":"Правилата за користење, копирање, менување или споделување нешто создадено од друг, како софтвер, фонтови или слики.","also":["licences","license","licenses","лиценци"],"noTip":1},{"id":"opensource","g":"money","word":"Отворен код","text":"Софтвер чиј код секој може да го чита, користи и често бесплатно да го менува, според правилата на лиценцата.","also":["open-source","open source software","OSS","софтвер со отворен код"]},{"id":"osslicence","g":"money","word":"Лиценца за отворен код","text":"Правилата што доаѓаат со отворениот код. Некои дозволуваат речиси сè, како MIT; други бараат да ги споделиш и промените, како GPL.","also":["open source licences","MIT licence","GPL","лиценци за отворен код"]},{"id":"proprietary","g":"money","word":"Сопственички софтвер","text":"Во сопственост на компанија и не е слободен за копирање или менување. Спротивно од отворен код.","also":["proprietary software","сопственички софтвер"]},{"id":"copyright","g":"money","word":"Авторско право","text":"Законското право на создавачот да го контролира копирањето на своето дело, вклучувајќи код и текст.","also":["copyrighted","заштитено со авторско право"],"noTip":1},{"id":"ip","g":"money","word":"Интелектуална сопственост (IP)","text":"Идеи и творби што законот ги третира како сопственост, како код, дизајни, имиња и логоа.","also":["intellectual property","интелектуална сопственост"]},{"id":"tos","g":"money","word":"Услови за користење","text":"Правилата со кои се согласуваш кога користиш услуга.","also":["terms and conditions","terms of use","општи услови"]},{"id":"contract","g":"money","word":"Договор","text":"Писмена спогодба меѓу две страни чие исполнување го поддржува законот.","also":["contracts","договори"],"noTip":1},{"id":"sow","g":"money","word":"Опис на работата (SOW)","text":"Документ што точно кажува која работа ќе се изврши, до кога и за колку пари.","also":["SOW"]},{"id":"fixedprice","g":"money","word":"Фиксна цена","text":"Договорена цена за целата работа, без оглед колку долго трае.","also":["fixed-price","фиксна цена"]},{"id":"tm","g":"money","word":"Време и материјали","text":"Плаќање за навистина одработените часови и искористените материјали, наместо однапред утврдена цена.","also":["T&M"]},{"id":"invoice","g":"money","word":"Фактура","text":"Сметка со која се бара плаќање за извршена работа или испорачана стока.","also":["invoices","фактури"],"noTip":1},{"id":"lockin","g":"money","word":"Зависност од добавувач","text":"Кога преминувањето кај друг добавувач е толку тешко или скапо што остануваш врзан за постојниот.","also":["lock-in","врзаност за добавувач"]},{"id":"procurement","g":"money","word":"Набавка","text":"Процесот на избирање добавувачи и купување од нив.","also":["набавки"]},{"id":"servicecredit","g":"money","word":"Надомест за услугата","text":"Вратени пари или попуст што го добиваш кога добавувачот не го исполнил SLA.","also":["service credits","надоместоци за услуга"]}]}};
